    'config.plateDuplicateError': 'A plate with this weight and diameter already exists.',
    'config.doubleProgressionTitle': 'Double Progression',
    'config.incrementSchemeDescription':
      'Double progression: two different progression modes for the same principle. Example with an 8-10 rep range.\n\n"Add a rep to every set" mode (simpler):\nSession 1: 3x8 (every set 8 reps)\nSuccess → Session 2: 3x9\nSuccess → Session 3: 3x10 (top of the range reached)\nSuccess → weight goes up, back to 3x8 with the new weight\n\n"Add one total extra rep" mode (gentler, example with 4 sets):\nSession 1: 4x8\nSuccess → Session 2: 1x9 + 3x8 (only one set gets the extra rep, not all at once)\nSuccess → Session 3: 2x9 + 2x8\nSuccess → Session 4: 3x9 + 1x8\nSuccess → Session 5: 4x9 (every set has now caught up to 9)\nSuccess → Session 6: 1x10 + 3x9\nSuccess → Session 7: 2x10 + 2x9\nSuccess → Session 8: 3x10 + 1x9\nSuccess → Session 9: 4x10 (top of the range reached)\nSuccess → weight goes up, back to 4x8\n\nThe point of this second mode: the increase spreads across more sessions (with 4 sets, a full cycle takes 9 sessions instead of just 3), since only a single total rep is added each session instead of one more on every set at once.\n\n"A set only counts once..." means: every individual set is checked against its own target for that session. If even one set misses its target (e.g. in 2x9+2x8, one of the 9-rep sets only manages 8), the whole session counts as unsuccessful - the next session repeats the exact same targets (no step back, but no progress either).',
    'config.incrementSchemeRepRange': 'Target Reps',
    'config.incrementSchemeModeAllSets': 'Add a rep to every set each session',
    'config.incrementSchemeModeOneTotalRep': 'Add one total extra rep each session',
    'config.repGoalTitle': 'Rep Goal System',
    'config.repGoalDescription':
      'Rep goal system: instead of a fixed target per set, each working set is pushed close to failure and logged freely. The reps from all working sets are added up at the end of the session (e.g. 8+8+6+6 = 28) and compared to the total rep goal. Surpass the goal and the weight goes up next session; fall short and the same weight repeats so you can try again.',
    'config.repGoalTotalRepGoalLabel': 'Rep goal',
    'config.waveProgressionTitle': 'Wave Progression',
    'config.waveProgressionDescription':
      'Wave progression: every working set always shares the same rep target and weight - unlike double progression, there\'s no per-set variation.\n\nExample with Initial reps 8, Final reps 6, Reps decrement 1, starting weight 100 kg:\nSession 1: 3x8 @100 kg\nSuccess → Session 2: 3x7 @101 kg\nSuccess → Session 3: 3x6 @102 kg (Final reps reached)\nSuccess → new wave, Session 4: 3x8 @101 kg (one increment above where the PREVIOUS wave started, not where it ended)\nSuccess → Session 5: 3x7 @102 kg\nSuccess → Session 6: 3x6 @103 kg\nSuccess → Session 7: 3x8 @102 kg (next wave)\n\nThe point: each full wave raises the wave\'s own starting weight by one increment, while within a wave the weight climbs higher for a while at the cost of fewer reps, instead of resetting all the way back down every time.\n\nEvery individual working set must reach at least the current rep target - if even one set misses it, the whole session counts as unsuccessful: weight and rep target stay exactly the same, and the next session repeats the identical attempt.',
    'config.waveProgressionInitialRepsLabel': 'Initial reps',
    'config.waveProgressionFinalRepsLabel': 'Final reps',
    'config.waveProgressionDecrementLabel': 'Reps decrement per session',
    'config.restsTitle': 'Rests',
    'config.restsOverrideHint': 'These values apply as the default for every exercise, and can be overridden individually in the exercises of training plans and training sessions.',
    'config.firstRestAfterSetLabel': '1st rest',
    'config.firstRestAfterSetTooltip': 'Wait time after a set ends until the first reminder gong.',
    'config.secondRestAfterSetLabel': '2nd rest',
    'config.secondRestAfterSetTooltip': 'Wait time after a set ends until the second gong - counted from the same moment, not on top of the 1st rest. Value ≤ 1st rest: only one gong.',
    'config.restBetweenExercisesLabel': 'Rest between exercises',
    'config.autoTrainingSessionTitle': 'Automated Training Session',
    'config.autoTrainingSessionHint':
      'Controls what happens once every set in a section is done: whether it automatically switches to the next section that still has open sets - if needed, even the next exercise.',
    'config.warmupSetsAutoAdvanceLabel': 'Warm-up Sets',
    'config.workingSetsAutoAdvanceLabel': 'Working Sets',
    'config.autoAdvanceImmediateOption': 'Move on right after the last set',
    'config.autoAdvanceConfirmOption': 'Ask first',
    'config.autoAdvanceOffOption': 'No automation',
    'sessions.autoAdvanceToWorkingQuestion': 'All warm-up sets are done. Switch to the working sets?',
    'sessions.autoAdvanceToCooldownQuestion': 'All working sets are done. Switch to the cooldown?',
    'sessions.autoAdvanceWarmupToCooldownQuestion': 'All warm-up sets are done. Switch to the cooldown?',
    'sessions.autoAdvanceToNextExerciseQuestion': 'All sets here are done. Switch to the next exercise?',
    'config.linearProgressionTitle': 'Linear Progression',
    'config.linearProgressionDescription':
      'Linear progression: the classic StrongLifts/Starting Strength style. Every working set must reach its own fixed minimum rep count (usually the same across sets, e.g. 3x5, but adjustable per set) for the weight to increase next session; miss even one set and the same weight repeats so you can try again. Unlike the other schemes here, there\'s no global default to configure - the minimum rep count is set directly on each exercise in its training plan. This is the default progression scheme for newly added exercises.',

