    'config.dumbbellEmpty': 'Noch keine Einträge.',
    'config.dumbbellDeleteConfirm': 'Diesen Eintrag wirklich löschen?',
    'config.dumbbellDuplicateError': 'Eine Hantel mit diesem Namen, Gewicht und Durchmesser existiert bereits.',
    'config.plateQuantity': 'Anzahl',
    'config.plateDuplicateError': 'Eine Scheibe mit diesem Gewicht und Durchmesser existiert bereits.',
    'config.doubleProgressionTitle': 'Doppel-Progression',
    'config.incrementSchemeDescription':
      'Doppelte Progression: zwei unterschiedliche Steigerungs-Modi für das gleiche Prinzip. Beispiel mit Wiederholungsbereich 8-10.\n\nModus „Jedem Satz eine Wiederholung hinzufügen" (einfacher):\nEinheit 1: 3x8 (alle Sätze 8 Wdh.)\nGeschafft → Einheit 2: 3x9\nGeschafft → Einheit 3: 3x10 (obere Grenze erreicht)\nGeschafft → Gewicht steigt, zurück zu 3x8 mit dem neuen Gewicht\n\nModus „Insgesamt eine Wiederholung hinzufügen" (sanfter, Beispiel mit 4 Sätzen):\nEinheit 1: 4x8\nGeschafft → Einheit 2: 1x9 + 3x8 (nur ein Satz bekommt die Extra-Wiederholung, nicht alle gleichzeitig)\nGeschafft → Einheit 3: 2x9 + 2x8\nGeschafft → Einheit 4: 3x9 + 1x8\nGeschafft → Einheit 5: 4x9 (jetzt sind alle bei 9 angekommen)\nGeschafft → Einheit 6: 1x10 + 3x9\nGeschafft → Einheit 7: 2x10 + 2x9\nGeschafft → Einheit 8: 3x10 + 1x9\nGeschafft → Einheit 9: 4x10 (obere Grenze erreicht)\nGeschafft → Gewicht steigt, zurück zu 4x8\n\nDer Sinn dieses zweiten Modus: Die Steigerung verteilt sich über mehr Einheiten (bei 4 Sätzen dauert ein voller Durchlauf 9 statt nur 3 Einheiten), weil pro Einheit nur eine einzige Wiederholung insgesamt dazukommt statt gleich bei jedem Satz eine mehr.\n\n„Ein Satz zählt nur, wenn..." bedeutet: Jeder einzelne Satz wird gegen sein eigenes Ziel dieser Einheit geprüft. Schafft auch nur ein Satz sein Ziel nicht (z. B. bei 2x9+2x8 macht einer der 9er-Sätze nur 8 Wdh.), gilt die ganze Einheit als nicht bestanden – die nächste Einheit wiederholt exakt dieselben Ziele (kein Rückschritt, aber auch kein Fortschritt).',
    'config.incrementSchemeRepRange': 'Ziel-Wdh.',
    'config.incrementSchemeModeAllSets': 'Jede Einheit eine Wiederholung zu jedem Satz hinzufügen',
    'config.incrementSchemeModeOneTotalRep': 'Jede Einheit eine Wiederholung insgesamt hinzufügen',
    'config.repGoalTitle': 'Wiederholungsziel-System',
    'config.repGoalDescription':
      'Wiederholungsziel-System: Statt eines festen Ziels pro Satz trainierst du jeden Arbeitssatz nah ans Muskelversagen und protokollierst frei. Die Wiederholungen aller Arbeitssätze werden am Ende der Einheit zusammengezählt (z. B. 8+8+6+6 = 28) und mit dem Wiederholungsziel verglichen. Übertriffst du das Ziel, steigt das Gewicht in der nächsten Einheit; verfehlst du es, bleibt das Gewicht gleich, und du versuchst es erneut.',
    'config.repGoalTotalRepGoalLabel': 'Wiederholungsziel',
    'config.waveProgressionTitle': 'Wellen-Progression',
    'config.waveProgressionDescription':
      'Wellen-Progression: Alle Arbeitssätze teilen sich immer dasselbe Wiederholungsziel und Gewicht - anders als bei Doppel-Progression gibt es keine satzweise unterschiedlichen Werte.\n\nBeispiel mit Anfangswiederholungen 8, Endwiederholungen 6, Wiederholungsreduktion 1, Startgewicht 100 kg:\nEinheit 1: 3x8 @100 kg\nGeschafft → Einheit 2: 3x7 @101 kg\nGeschafft → Einheit 3: 3x6 @102 kg (Endwiederholungen erreicht)\nGeschafft → neue Welle, Einheit 4: 3x8 @101 kg (eine Steigerung über dem Start der VORHERIGEN Welle, nicht dort wo sie endete)\nGeschafft → Einheit 5: 3x7 @102 kg\nGeschafft → Einheit 6: 3x6 @103 kg\nGeschafft → Einheit 7: 3x8 @102 kg (nächste Welle)\n\nDer Sinn: Jeder vollständige Wellendurchlauf hebt den eigenen Wellenstart um eine Steigerung an, während innerhalb einer Welle das Gewicht vorübergehend höher steigt, dafür mit weniger Wiederholungen - statt jedes Mal komplett zurückzufallen.\n\nJeder einzelne Arbeitssatz muss mindestens das aktuelle Wiederholungsziel erreichen - schafft auch nur ein Satz das nicht, gilt die ganze Einheit als nicht bestanden: Gewicht und Wiederholungsziel bleiben exakt gleich, die nächste Einheit wiederholt denselben Versuch.',
    'config.waveProgressionInitialRepsLabel': 'Anfangswiederholungen',
    'config.waveProgressionFinalRepsLabel': 'Endwiederholungen',
    'config.waveProgressionDecrementLabel': 'Wiederholungsreduktion pro Einheit',
    'config.restsTitle': 'Pausen',
    'config.restsOverrideHint': 'Diese Werte gelten als Standard für alle Übungen und können in den Übungen der Trainingspläne und Trainingseinheiten individuell überschrieben werden.',
    'config.firstRestAfterSetLabel': '1. Pause',
    'config.firstRestAfterSetTooltip': 'Wartezeit nach Satzende bis zum ersten Erinnerungston (Gong).',
    'config.secondRestAfterSetLabel': '2. Pause',
    'config.secondRestAfterSetTooltip': 'Wartezeit nach Satzende bis zum zweiten Gong – ab demselben Zeitpunkt gezählt, nicht zusätzlich zur 1. Pause. Wert ≤ 1. Pause: nur ein Gong.',
    'config.restBetweenExercisesLabel': 'Pause zwischen den Übungen',
    'config.autoTrainingSessionTitle': 'Automatisierte Trainingseinheit',
    'config.autoTrainingSessionHint':
      'Legt fest, was passiert, sobald alle Sätze einer Sektion abgeschlossen sind: ob automatisch zur nächsten Sektion mit offenen Sätzen gewechselt wird - gegebenenfalls auch zur nächsten Übung.',
    'config.warmupSetsAutoAdvanceLabel': 'Aufwärm-Sätze',
    'config.workingSetsAutoAdvanceLabel': 'Arbeits-Sätze',
    'config.autoAdvanceImmediateOption': 'Nach dem letzten Satz sofort weiter',
    'config.autoAdvanceConfirmOption': 'Vorher fragen',
    'config.autoAdvanceOffOption': 'Keine Automatik',
    'sessions.autoAdvanceToWorkingQuestion': 'Alle Aufwärmsätze sind erledigt. Zu den Arbeitssätzen wechseln?',
    'sessions.autoAdvanceToCooldownQuestion': 'Alle Arbeitssätze sind erledigt. Zum Cool-Down wechseln?',
    'sessions.autoAdvanceWarmupToCooldownQuestion': 'Alle Aufwärmsätze sind erledigt. Zum Cool-Down wechseln?',
    'sessions.autoAdvanceToNextExerciseQuestion': 'Alle Sätze hier sind erledigt. Zur nächsten Übung wechseln?',
    'config.linearProgressionTitle': 'Lineare Progression',
    'config.linearProgressionDescription':
      'Lineare Progression: der klassische StrongLifts-/Starting-Strength-Stil. Jeder Arbeitssatz muss seine eigene feste Mindestwiederholungszahl erreichen (meist für alle Sätze gleich gewählt, z. B. 3x5, aber pro Satz einzeln einstellbar), damit das Gewicht in der nächsten Einheit steigt; verfehlst du auch nur einen Satz, wiederholt sich die gleiche Gewichtsvorgabe unverändert. Anders als bei den übrigen Schemata hier gibt es keine globale Voreinstellung – die Mindestwiederholungszahl wird direkt pro Übung im Trainingsplan festgelegt. Dies ist das Standard-Progressionsschema für neu hinzugefügte Übungen.',

