    'config.doubleProgressionTitle': 'Progresión doble',
    'config.incrementSchemeDescription':
      'Progresión doble: dos modos de progresión distintos para el mismo principio. Ejemplo con un rango de repeticiones de 8-10.\n\nModo «Añadir una repetición a cada serie» (más simple):\nSesión 1: 3x8 (todas las series 8 reps)\nLograda → Sesión 2: 3x9\nLograda → Sesión 3: 3x10 (límite superior alcanzado)\nLograda → el peso sube, vuelta a 3x8 con el nuevo peso\n\nModo «Añadir una repetición total» (más suave, ejemplo con 4 series):\nSesión 1: 4x8\nLograda → Sesión 2: 1x9 + 3x8 (solo una serie recibe la repetición extra, no todas a la vez)\nLograda → Sesión 3: 2x9 + 2x8\nLograda → Sesión 4: 3x9 + 1x8\nLograda → Sesión 5: 4x9 (ahora todas han alcanzado 9)\nLograda → Sesión 6: 1x10 + 3x9\nLograda → Sesión 7: 2x10 + 2x9\nLograda → Sesión 8: 3x10 + 1x9\nLograda → Sesión 9: 4x10 (límite superior alcanzado)\nLograda → el peso sube, vuelta a 4x8\n\nEl sentido de este segundo modo: el aumento se reparte entre más sesiones (con 4 series, un ciclo completo tarda 9 sesiones en vez de solo 3), porque cada sesión solo se añade una repetición en total en lugar de una más en cada serie a la vez.\n\n«Una serie solo cuenta si...» significa: cada serie se comprueba individualmente contra su propio objetivo de esa sesión. Si aunque sea una serie falla su objetivo (p. ej., en 2x9+2x8 una de las series de 9 solo logra 8), toda la sesión se considera no superada - la siguiente sesión repite exactamente los mismos objetivos (sin retroceso, pero tampoco sin avance).',
    'config.incrementSchemeRepRange': 'Objetivo reps',
    'config.incrementSchemeModeAllSets': 'Añadir una repetición a cada serie por sesión',
    'config.incrementSchemeModeOneTotalRep': 'Añadir una repetición total por sesión',
    'config.repGoalTitle': 'Sistema de meta de repeticiones',
    'config.repGoalDescription':
      'Sistema de meta de repeticiones: en lugar de un objetivo fijo por serie, cada serie de trabajo se lleva cerca del fallo muscular y se registra libremente. Las repeticiones de todas las series de trabajo se suman al final de la sesión (p. ej. 8+8+6+6 = 28) y se comparan con la meta total de repeticiones. Si superas la meta, el peso sube en la siguiente sesión; si no la alcanzas, el peso se mantiene para que lo intentes de nuevo.',
    'config.repGoalTotalRepGoalLabel': 'Meta de repeticiones',
    'config.waveProgressionTitle': 'Progresión ondulante',
    'config.waveProgressionDescription':
      'Progresión ondulante: todas las series de trabajo comparten siempre el mismo objetivo de repeticiones y el mismo peso - a diferencia de la progresión doble, no hay variación por serie.\n\nEjemplo con Repeticiones iniciales 8, Repeticiones finales 6, Reducción de repeticiones 1, peso inicial 100 kg:\nSesión 1: 3x8 @100 kg\nLograda → Sesión 2: 3x7 @101 kg\nLograda → Sesión 3: 3x6 @102 kg (Repeticiones finales alcanzadas)\nLograda → nueva ola, Sesión 4: 3x8 @101 kg (un incremento por encima de donde empezó la ola ANTERIOR, no donde terminó)\nLograda → Sesión 5: 3x7 @102 kg\nLograda → Sesión 6: 3x6 @103 kg\nLograda → Sesión 7: 3x8 @102 kg (siguiente ola)\n\nEl sentido: cada ola completa eleva el propio peso de inicio de la ola en un incremento, mientras que dentro de una ola el peso sube más por un tiempo a costa de menos repeticiones, en lugar de volver del todo al principio cada vez.\n\nCada serie de trabajo individual debe alcanzar al menos el objetivo de repeticiones actual - si aunque sea una serie no lo logra, toda la sesión se considera fallida: el peso y el objetivo de repeticiones se mantienen exactamente igual, y la siguiente sesión repite el mismo intento.',
    'config.waveProgressionInitialRepsLabel': 'Repeticiones iniciales',
    'config.waveProgressionFinalRepsLabel': 'Repeticiones finales',
    'config.waveProgressionDecrementLabel': 'Reducción de repeticiones por sesión',
    'config.restsTitle': 'Descansos',
    'config.restsOverrideHint': 'Estos valores se aplican como predeterminados para todos los ejercicios y pueden anularse individualmente en los ejercicios de los planes y las sesiones de entrenamiento.',
    'config.firstRestAfterSetLabel': '1.ª pausa',
    'config.firstRestAfterSetTooltip': 'Tiempo de espera tras terminar una serie hasta el primer gong de aviso.',
    'config.secondRestAfterSetLabel': '2.ª pausa',
    'config.secondRestAfterSetTooltip': 'Tiempo de espera tras terminar una serie hasta el segundo gong: contado desde el mismo momento que el primero, no adicional. Valor ≤ 1.ª pausa: solo un gong.',
    'config.restBetweenExercisesLabel': 'Descanso entre ejercicios',
    'config.autoTrainingSessionTitle': 'Sesión de entrenamiento automatizada',
    'config.autoTrainingSessionHint':
      'Define qué ocurre cuando todas las series de una sección están hechas: si se cambia automáticamente a la siguiente sección con series pendientes, incluso al siguiente ejercicio si hace falta.',
    'config.warmupSetsAutoAdvanceLabel': 'Series de calentamiento',
    'config.workingSetsAutoAdvanceLabel': 'Series de trabajo',
    'config.autoAdvanceImmediateOption': 'Continuar automáticamente tras la última serie',
    'config.autoAdvanceConfirmOption': 'Preguntar antes',
    'config.autoAdvanceOffOption': 'Sin automatización',
    'sessions.autoAdvanceToWorkingQuestion': 'Todas las series de calentamiento están hechas. ¿Cambiar a las series de trabajo?',
    'sessions.autoAdvanceToCooldownQuestion': 'Todas las series de trabajo están hechas. ¿Cambiar al enfriamiento?',
    'sessions.autoAdvanceWarmupToCooldownQuestion': 'Todas las series de calentamiento están hechas. ¿Cambiar al enfriamiento?',
    'sessions.autoAdvanceToNextExerciseQuestion': 'Todas las series aquí están hechas. ¿Cambiar al siguiente ejercicio?',
    'config.linearProgressionTitle': 'Progresión lineal',
    'config.linearProgressionDescription':
      'Progresión lineal: el estilo clásico de StrongLifts/Starting Strength. Cada serie de trabajo debe alcanzar su propio número mínimo fijo de repeticiones (normalmente igual en todas las series, p. ej. 3x5, pero ajustable por serie) para que el peso suba en la siguiente sesión; si fallas aunque sea una serie, el mismo peso se repite para que lo intentes de nuevo. A diferencia de los demás esquemas, aquí no hay una configuración global predeterminada: el número mínimo de repeticiones se establece directamente en cada ejercicio del plan de entrenamiento. Este es el esquema de progresión predeterminado para los ejercicios recién añadidos.',

