    'config.doubleProgressionTitle': 'Progressão dupla',
    'config.incrementSchemeDescription':
      'Progressão dupla: dois modos de progressão diferentes para o mesmo princípio. Exemplo com uma faixa de repetições de 8-10.\n\nModo "Adicionar uma repetição a cada série" (mais simples):\nSessão 1: 3x8 (todas as séries 8 reps)\nConseguiu → Sessão 2: 3x9\nConseguiu → Sessão 3: 3x10 (limite superior atingido)\nConseguiu → o peso aumenta, de volta a 3x8 com o novo peso\n\nModo "Adicionar uma repetição total" (mais suave, exemplo com 4 séries):\nSessão 1: 4x8\nConseguiu → Sessão 2: 1x9 + 3x8 (apenas uma série ganha a repetição extra, não todas de uma vez)\nConseguiu → Sessão 3: 2x9 + 2x8\nConseguiu → Sessão 4: 3x9 + 1x8\nConseguiu → Sessão 5: 4x9 (agora todas chegaram a 9)\nConseguiu → Sessão 6: 1x10 + 3x9\nConseguiu → Sessão 7: 2x10 + 2x9\nConseguiu → Sessão 8: 3x10 + 1x9\nConseguiu → Sessão 9: 4x10 (limite superior atingido)\nConseguiu → o peso aumenta, de volta a 4x8\n\nO sentido deste segundo modo: o aumento se espalha por mais sessões (com 4 séries, um ciclo completo leva 9 sessões em vez de apenas 3), porque a cada sessão só se soma uma repetição no total, em vez de uma a mais em cada série de uma vez.\n\n"Uma série só conta quando..." significa: cada série é verificada individualmente contra sua própria meta daquela sessão. Se mesmo uma série não atingir sua meta (ex.: em 2x9+2x8, uma das séries de 9 só consegue 8), a sessão inteira é considerada malsucedida - a próxima sessão repete exatamente as mesmas metas (sem retrocesso, mas também sem progresso).',
    'config.incrementSchemeRepRange': 'Alvo reps',
    'config.incrementSchemeModeAllSets': 'Adicionar uma repetição a cada série por sessão',
    'config.incrementSchemeModeOneTotalRep': 'Adicionar uma repetição total por sessão',
    'config.repGoalTitle': 'Sistema de meta de repetições',
    'config.repGoalDescription':
      'Sistema de meta de repetições: em vez de uma meta fixa por série, cada série de trabalho é levada perto da falha muscular e registrada livremente. As repetições de todas as séries de trabalho são somadas ao final da sessão (ex.: 8+8+6+6 = 28) e comparadas com a meta total de repetições. Se você ultrapassar a meta, o peso aumenta na próxima sessão; se não atingir, o peso permanece o mesmo para você tentar novamente.',
    'config.repGoalTotalRepGoalLabel': 'Meta de repetições',
    'config.waveProgressionTitle': 'Progressão ondulatória',
    'config.waveProgressionDescription':
      'Progressão ondulatória: todas as séries de trabalho compartilham sempre a mesma meta de repetições e o mesmo peso - ao contrário da progressão dupla, não há variação por série.\n\nExemplo com Repetições iniciais 8, Repetições finais 6, Redução de repetições 1, peso inicial 100 kg:\nSessão 1: 3x8 @100 kg\nConseguiu → Sessão 2: 3x7 @101 kg\nConseguiu → Sessão 3: 3x6 @102 kg (Repetições finais atingidas)\nConseguiu → nova onda, Sessão 4: 3x8 @101 kg (um incremento acima de onde a onda ANTERIOR começou, não onde terminou)\nConseguiu → Sessão 5: 3x7 @102 kg\nConseguiu → Sessão 6: 3x6 @103 kg\nConseguiu → Sessão 7: 3x8 @102 kg (próxima onda)\n\nO sentido: cada onda completa eleva o próprio peso inicial da onda em um incremento, enquanto dentro de uma onda o peso sobe mais por um tempo às custas de menos repetições, em vez de voltar totalmente ao início toda vez.\n\nCada série de trabalho individual deve atingir pelo menos a meta de repetições atual - se mesmo uma série não atingir, a sessão inteira é considerada malsucedida: o peso e a meta de repetições permanecem exatamente iguais, e a próxima sessão repete a mesma tentativa.',
    'config.waveProgressionInitialRepsLabel': 'Repetições iniciais',
    'config.waveProgressionFinalRepsLabel': 'Repetições finais',
    'config.waveProgressionDecrementLabel': 'Redução de repetições por sessão',
    'config.restsTitle': 'Pausas',
    'config.restsOverrideHint': 'Esses valores se aplicam como padrão para todos os exercícios e podem ser substituídos individualmente nos exercícios dos planos e sessões de treino.',
    'config.firstRestAfterSetLabel': '1.ª pausa',
    'config.firstRestAfterSetTooltip': 'Tempo de espera após o fim de uma série até o primeiro gongo de aviso.',
    'config.secondRestAfterSetLabel': '2.ª pausa',
    'config.secondRestAfterSetTooltip': 'Tempo de espera após o fim de uma série até o segundo gongo – contado a partir do mesmo momento que o primeiro, não somado a ele. Valor ≤ 1.ª pausa: apenas um gongo.',
    'config.restBetweenExercisesLabel': 'Pausa entre exercícios',
    'config.autoTrainingSessionTitle': 'Sessão de treino automatizada',
    'config.autoTrainingSessionHint':
      'Define o que acontece quando todas as séries de uma seção estão concluídas: se muda automaticamente para a próxima seção com séries pendentes - se necessário, até para o próximo exercício.',
    'config.warmupSetsAutoAdvanceLabel': 'Séries de aquecimento',
    'config.workingSetsAutoAdvanceLabel': 'Séries de trabalho',
    'config.autoAdvanceImmediateOption': 'Avançar automaticamente após a última série',
    'config.autoAdvanceConfirmOption': 'Perguntar antes',
    'config.autoAdvanceOffOption': 'Sem automação',
    'sessions.autoAdvanceToWorkingQuestion': 'Todas as séries de aquecimento foram concluídas. Mudar para as séries de trabalho?',
    'sessions.autoAdvanceToCooldownQuestion': 'Todas as séries de trabalho foram concluídas. Mudar para o desaquecimento?',
    'sessions.autoAdvanceWarmupToCooldownQuestion': 'Todas as séries de aquecimento foram concluídas. Mudar para o desaquecimento?',
    'sessions.autoAdvanceToNextExerciseQuestion': 'Todas as séries aqui foram concluídas. Mudar para o próximo exercício?',
    'config.linearProgressionTitle': 'Progressão linear',
    'config.linearProgressionDescription':
      'Progressão linear: o estilo clássico do StrongLifts/Starting Strength. Cada série de trabalho deve atingir o seu próprio número mínimo fixo de repetições (normalmente igual em todas as séries, ex.: 3x5, mas ajustável por série) para que o peso aumente na próxima sessão; se você errar mesmo que uma série, o mesmo peso se repete para você tentar novamente. Ao contrário dos demais esquemas, aqui não há uma configuração global padrão: o número mínimo de repetições é definido diretamente em cada exercício do plano de treino. Este é o esquema de progressão padrão para exercícios recém-adicionados.',

