    'config.equipmentTitle': 'Attrezzatura',
    'config.equipmentDumbbellsTab': 'Manubri',
    'config.equipmentPlatesTab': 'Dischi',
    'config.dumbbellName': 'Nome',
    'config.dumbbellWeight': 'Peso',
    'config.dumbbellAdd': 'Aggiungi',
    'config.dumbbellEmpty': 'Nessuna voce ancora.',
    'config.dumbbellDeleteConfirm': 'Eliminare davvero questa voce?',
    'config.dumbbellDuplicateError': 'Esiste già un manubrio con questo nome, peso e diametro.',
    'config.plateQuantity': 'Qtà',
    'config.plateDuplicateError': 'Esiste già un disco con questo peso e diametro.',
    'config.doubleProgressionTitle': 'Progressione doppia',
    'config.incrementSchemeDescription':
      'Progressione doppia: due diverse modalità di progressione per lo stesso principio. Esempio con un intervallo di ripetizioni 8-10.\n\nModalità "Aggiungi una ripetizione a ogni serie" (più semplice):\nSessione 1: 3x8 (tutte le serie 8 rip.)\nRiuscita → Sessione 2: 3x9\nRiuscita → Sessione 3: 3x10 (limite superiore raggiunto)\nRiuscita → il peso aumenta, si torna a 3x8 con il nuovo peso\n\nModalità "Aggiungi una ripetizione totale" (più graduale, esempio con 4 serie):\nSessione 1: 4x8\nRiuscita → Sessione 2: 1x9 + 3x8 (solo una serie riceve la ripetizione extra, non tutte insieme)\nRiuscita → Sessione 3: 2x9 + 2x8\nRiuscita → Sessione 4: 3x9 + 1x8\nRiuscita → Sessione 5: 4x9 (ora tutte hanno raggiunto 9)\nRiuscita → Sessione 6: 1x10 + 3x9\nRiuscita → Sessione 7: 2x10 + 2x9\nRiuscita → Sessione 8: 3x10 + 1x9\nRiuscita → Sessione 9: 4x10 (limite superiore raggiunto)\nRiuscita → il peso aumenta, si torna a 4x8\n\nIl senso di questa seconda modalità: l\'aumento si distribuisce su più sessioni (con 4 serie, un ciclo completo richiede 9 sessioni invece di solo 3), perché ogni sessione si aggiunge una sola ripetizione totale invece di una in più su ogni serie contemporaneamente.\n\n"Una serie conta solo se..." significa: ogni singola serie viene verificata rispetto al proprio obiettivo di quella sessione. Se anche una sola serie non raggiunge il suo obiettivo (es. in 2x9+2x8 una delle serie da 9 fa solo 8), l\'intera sessione è considerata non riuscita - la sessione successiva ripete esattamente gli stessi obiettivi (nessun passo indietro, ma nemmeno un progresso).',
    'config.incrementSchemeRepRange': 'Rip. previste',
    'config.incrementSchemeModeAllSets': 'Aggiungi una ripetizione a ogni serie per sessione',
    'config.incrementSchemeModeOneTotalRep': 'Aggiungi una ripetizione totale per sessione',
    'config.repGoalTitle': 'Sistema obiettivo ripetizioni',
    'config.repGoalDescription':
      'Sistema obiettivo ripetizioni: invece di un obiettivo fisso per serie, ogni serie di lavoro viene portata vicino al cedimento e registrata liberamente. Le ripetizioni di tutte le serie di lavoro vengono sommate alla fine della sessione (es. 8+8+6+6 = 28) e confrontate con l\'obiettivo totale di ripetizioni. Se superi l\'obiettivo, il peso aumenta nella sessione successiva; se non lo raggiungi, il peso resta invariato per riprovare.',
    'config.repGoalTotalRepGoalLabel': 'Obiettivo ripetizioni',
    'config.waveProgressionTitle': 'Progressione a onde',
    'config.waveProgressionDescription':
      'Progressione a onde: tutte le serie di lavoro condividono sempre lo stesso obiettivo di ripetizioni e lo stesso peso - a differenza della progressione doppia, non c\'è variazione per serie.\n\nEsempio con Ripetizioni iniziali 8, Ripetizioni finali 6, Riduzione ripetizioni 1, peso di partenza 100 kg:\nSessione 1: 3x8 @100 kg\nRiuscita → Sessione 2: 3x7 @101 kg\nRiuscita → Sessione 3: 3x6 @102 kg (Ripetizioni finali raggiunte)\nRiuscita → nuova onda, Sessione 4: 3x8 @101 kg (un incremento sopra il punto di partenza dell\'onda PRECEDENTE, non dove è finita)\nRiuscita → Sessione 5: 3x7 @102 kg\nRiuscita → Sessione 6: 3x6 @103 kg\nRiuscita → Sessione 7: 3x8 @102 kg (onda successiva)\n\nIl senso: ogni onda completa alza il proprio peso di partenza di un incremento, mentre all\'interno di un\'onda il peso sale più in alto per un po\' a costo di meno ripetizioni, invece di tornare completamente all\'inizio ogni volta.\n\nOgni singola serie di lavoro deve raggiungere almeno l\'obiettivo di ripetizioni attuale - se anche solo una serie non lo raggiunge, l\'intera sessione è considerata non riuscita: peso e obiettivo di ripetizioni restano esattamente gli stessi, e la sessione successiva ripete lo stesso tentativo.',
    'config.waveProgressionInitialRepsLabel': 'Ripetizioni iniziali',
    'config.waveProgressionFinalRepsLabel': 'Ripetizioni finali',
    'config.waveProgressionDecrementLabel': 'Riduzione ripetizioni per sessione',
    'config.restsTitle': 'Pause',
    'config.restsOverrideHint': 'Questi valori si applicano come predefiniti per ogni esercizio e possono essere sovrascritti singolarmente negli esercizi dei piani e delle sessioni di allenamento.',
    'config.firstRestAfterSetLabel': '1ª pausa',
    'config.firstRestAfterSetTooltip': 'Tempo di attesa dalla fine di una serie al primo gong di avviso.',
    'config.secondRestAfterSetLabel': '2ª pausa',
    'config.secondRestAfterSetTooltip': 'Tempo di attesa dalla fine di una serie al secondo gong – calcolato dallo stesso momento del primo, non in aggiunta. Valore ≤ 1ª pausa: un solo gong.',
    'config.restBetweenExercisesLabel': 'Pausa tra gli esercizi',
    'config.autoTrainingSessionTitle': 'Sessione di allenamento automatizzata',
    'config.autoTrainingSessionHint':
      "Stabilisce cosa succede quando tutte le serie di una sezione sono completate: se si passa automaticamente alla sezione successiva con serie ancora da fare - se necessario, anche all'esercizio successivo.",
    'config.warmupSetsAutoAdvanceLabel': 'Serie di riscaldamento',
    'config.workingSetsAutoAdvanceLabel': 'Serie di lavoro',
    'config.autoAdvanceImmediateOption': "Prosegui automaticamente dopo l'ultima serie",
    'config.autoAdvanceConfirmOption': 'Chiedi prima',
    'config.autoAdvanceOffOption': 'Nessuna automazione',
    'sessions.autoAdvanceToWorkingQuestion': 'Tutte le serie di riscaldamento sono completate. Passare alle serie di lavoro?',
    'sessions.autoAdvanceToCooldownQuestion': 'Tutte le serie di lavoro sono completate. Passare al defaticamento?',
    'sessions.autoAdvanceWarmupToCooldownQuestion': 'Tutte le serie di riscaldamento sono completate. Passare al defaticamento?',
    'sessions.autoAdvanceToNextExerciseQuestion': "Tutte le serie qui sono completate. Passare all'esercizio successivo?",
    'config.linearProgressionTitle': 'Progressione lineare',
    'config.linearProgressionDescription':
      'Progressione lineare: lo stile classico di StrongLifts/Starting Strength. Ogni serie di lavoro deve raggiungere il proprio numero minimo fisso di ripetizioni (di solito uguale per tutte le serie, es. 3x5, ma regolabile per singola serie) affinché il peso aumenti nella sessione successiva; se manchi anche una sola serie, lo stesso peso si ripete per riprovare. A differenza degli altri schemi, qui non c\'è un\'impostazione globale predefinita: il numero minimo di ripetizioni viene impostato direttamente su ogni esercizio nel piano di allenamento. Questo è lo schema di progressione predefinito per gli esercizi appena aggiunti.',

