    'config.dumbbellEmpty': 'Nog geen items.',
    'config.dumbbellDeleteConfirm': 'Dit item echt verwijderen?',
    'config.dumbbellDuplicateError': 'Er bestaat al een dumbbell met deze naam, gewicht en diameter.',
    'config.plateQuantity': 'Aantal',
    'config.plateDuplicateError': 'Er bestaat al een schijf met dit gewicht en deze diameter.',
    'config.doubleProgressionTitle': 'Dubbele progressie',
    'config.incrementSchemeDescription':
      'Dubbele progressie: twee verschillende progressiemodi voor hetzelfde principe. Voorbeeld met een herhalingsbereik van 8-10.\n\nModus "Voeg een herhaling toe aan elke set" (eenvoudiger):\nSessie 1: 3x8 (alle sets 8 herh.)\nGelukt → Sessie 2: 3x9\nGelukt → Sessie 3: 3x10 (bovengrens bereikt)\nGelukt → gewicht gaat omhoog, terug naar 3x8 met het nieuwe gewicht\n\nModus "Voeg in totaal één herhaling toe" (zachter, voorbeeld met 4 sets):\nSessie 1: 4x8\nGelukt → Sessie 2: 1x9 + 3x8 (maar één set krijgt de extra herhaling, niet allemaal tegelijk)\nGelukt → Sessie 3: 2x9 + 2x8\nGelukt → Sessie 4: 3x9 + 1x8\nGelukt → Sessie 5: 4x9 (nu zijn ze allemaal bij 9 aangekomen)\nGelukt → Sessie 6: 1x10 + 3x9\nGelukt → Sessie 7: 2x10 + 2x9\nGelukt → Sessie 8: 3x10 + 1x9\nGelukt → Sessie 9: 4x10 (bovengrens bereikt)\nGelukt → gewicht gaat omhoog, terug naar 4x8\n\nHet nut van deze tweede modus: de toename spreidt zich over meer sessies (bij 4 sets duurt een volledige cyclus 9 in plaats van maar 3 sessies), omdat er per sessie maar één herhaling in totaal bijkomt in plaats van meteen één extra bij elke set.\n\n"Een set telt alleen mee als..." betekent: elke afzonderlijke set wordt getoetst aan zijn eigen doel van die sessie. Haalt ook maar één set zijn doel niet (bijv. bij 2x9+2x8 haalt een van de 9-sets maar 8), dan telt de hele sessie als niet gelukt - de volgende sessie herhaalt exact dezelfde doelen (geen stap terug, maar ook geen vooruitgang).',
    'config.incrementSchemeRepRange': 'Doel herh.',
    'config.incrementSchemeModeAllSets': 'Elke sessie een herhaling toevoegen aan elke set',
    'config.incrementSchemeModeOneTotalRep': 'Elke sessie in totaal één herhaling toevoegen',
    'config.repGoalTitle': 'Herhalingsdoel-systeem',
    'config.repGoalDescription':
      'Herhalingsdoel-systeem: in plaats van een vast doel per set, breng je elke werkset dicht bij spierfalen en noteer je vrij. De herhalingen van alle werksets worden aan het einde van de sessie opgeteld (bijv. 8+8+6+6 = 28) en vergeleken met het totale herhalingsdoel. Overschrijd je het doel, dan gaat het gewicht omhoog in de volgende sessie; haal je het niet, dan blijft het gewicht gelijk zodat je het opnieuw kunt proberen.',
    'config.repGoalTotalRepGoalLabel': 'Herhalingsdoel',
    'config.waveProgressionTitle': 'Golfprogressie',
    'config.waveProgressionDescription':
      'Golfprogressie: alle werksets delen altijd hetzelfde herhalingsdoel en gewicht - anders dan bij dubbele progressie is er geen variatie per set.\n\nVoorbeeld met Beginherhalingen 8, Eindherhalingen 6, Herhalingsafname 1, startgewicht 100 kg:\nSessie 1: 3x8 @100 kg\nGelukt → Sessie 2: 3x7 @101 kg\nGelukt → Sessie 3: 3x6 @102 kg (Eindherhalingen bereikt)\nGelukt → nieuwe golf, Sessie 4: 3x8 @101 kg (één stap hoger dan waar de VORIGE golf begon, niet waar hij eindigde)\nGelukt → Sessie 5: 3x7 @102 kg\nGelukt → Sessie 6: 3x6 @103 kg\nGelukt → Sessie 7: 3x8 @102 kg (volgende golf)\n\nHet nut: elke volledige golf verhoogt het eigen startgewicht van de golf met één stap, terwijl het gewicht binnen een golf tijdelijk hoger gaat ten koste van minder herhalingen, in plaats van elke keer helemaal terug te vallen.\n\nElke afzonderlijke werkset moet minstens het huidige herhalingsdoel halen - haalt ook maar één set dit niet, dan telt de hele sessie als niet gelukt: gewicht en herhalingsdoel blijven precies hetzelfde, en de volgende sessie herhaalt exact dezelfde poging.',
    'config.waveProgressionInitialRepsLabel': 'Beginherhalingen',
    'config.waveProgressionFinalRepsLabel': 'Eindherhalingen',
    'config.waveProgressionDecrementLabel': 'Herhalingsafname per sessie',
    'config.restsTitle': 'Pauzes',
    'config.restsOverrideHint': 'Deze waarden gelden als standaard voor elke oefening en kunnen individueel worden overschreven bij de oefeningen van trainingsplannen en trainingssessies.',
    'config.firstRestAfterSetLabel': '1e pauze',
    'config.firstRestAfterSetTooltip': 'Wachttijd na het einde van een set tot de eerste herinneringsgong.',
    'config.secondRestAfterSetLabel': '2e pauze',
    'config.secondRestAfterSetTooltip': 'Wachttijd na het einde van een set tot de tweede gong – vanaf hetzelfde moment geteld, niet extra. Waarde ≤ 1e pauze: slechts één gong.',
    'config.restBetweenExercisesLabel': 'Pauze tussen oefeningen',
    'config.autoTrainingSessionTitle': 'Geautomatiseerde trainingssessie',
    'config.autoTrainingSessionHint':
      'Bepaalt wat er gebeurt zodra alle sets van een sectie voltooid zijn: of automatisch wordt overgeschakeld naar de volgende sectie met openstaande sets - indien nodig zelfs naar de volgende oefening.',
    'config.warmupSetsAutoAdvanceLabel': 'Warming-up sets',
