    'sessions.autoAdvanceToNextExerciseQuestion': 'Alle sets hier zijn voltooid. Overschakelen naar de volgende oefening?',
    'config.linearProgressionTitle': 'Lineaire progressie',
    'config.linearProgressionDescription':
      'Lineaire progressie: de klassieke StrongLifts-/Starting Strength-stijl. Elke werkset moet zijn eigen vaste minimumaantal herhalingen halen (meestal voor alle sets gelijk, bijv. 3x5, maar per set instelbaar) voordat het gewicht in de volgende sessie omhoog gaat; mis je ook maar één set, dan wordt hetzelfde gewicht herhaald zodat je het opnieuw kunt proberen. In tegenstelling tot de andere schema\'s is er hier geen algemene standaardinstelling: het minimumaantal herhalingen wordt direct per oefening in het trainingsplan ingesteld. Dit is het standaard progressieschema voor nieuw toegevoegde oefeningen.',

