    'trainingPlans.weightIncrementTooltip':
      'Ile ciężaru (lub, w zależności od wybranego po prawej typu, ile procent) jest dodawane po udanej sesji. Zastępuje domyślny przyrost (1).',
    'trainingPlans.incrementTypeLabel': 'Typ progresji',
