    'config.dumbbellDuplicateError': 'Hantla o tej nazwie, ciężarze i średnicy już istnieje.',
    'config.plateQuantity': 'Ilość',
    'config.plateDuplicateError': 'Talerz o tym ciężarze i średnicy już istnieje.',
    'config.doubleProgressionTitle': 'Podwójna progresja',
    'config.incrementSchemeDescription':
      'Podwójna progresja: dwa różne tryby progresji dla tej samej zasady. Przykład dla zakresu powtórzeń 8-10.\n\nTryb „Dodaj powtórzenie do każdej serii" (prostszy):\nSesja 1: 3x8 (wszystkie serie po 8 powt.)\nUdało się → Sesja 2: 3x9\nUdało się → Sesja 3: 3x10 (osiągnięto górną granicę)\nUdało się → ciężar rośnie, powrót do 3x8 z nowym ciężarem\n\nTryb „Dodaj jedno powtórzenie łącznie" (łagodniejszy, przykład z 4 seriami):\nSesja 1: 4x8\nUdało się → Sesja 2: 1x9 + 3x8 (tylko jedna seria dostaje dodatkowe powtórzenie, nie wszystkie naraz)\nUdało się → Sesja 3: 2x9 + 2x8\nUdało się → Sesja 4: 3x9 + 1x8\nUdało się → Sesja 5: 4x9 (teraz wszystkie doszły do 9)\nUdało się → Sesja 6: 1x10 + 3x9\nUdało się → Sesja 7: 2x10 + 2x9\nUdało się → Sesja 8: 3x10 + 1x9\nUdało się → Sesja 9: 4x10 (osiągnięto górną granicę)\nUdało się → ciężar rośnie, powrót do 4x8\n\nSens tego drugiego trybu: wzrost rozkłada się na więcej sesji (przy 4 seriach pełny cykl trwa 9 zamiast tylko 3 sesji), bo w każdej sesji dochodzi tylko jedno powtórzenie łącznie, zamiast od razu jednego więcej w każdej serii.\n\n„Seria liczy się tylko, gdy..." oznacza: każda pojedyncza seria jest sprawdzana względem własnego celu tej sesji. Jeśli choć jedna seria nie osiągnie celu (np. przy 2x9+2x8 jedna z serii na 9 wykona tylko 8), cała sesja liczy się jako nieudana - kolejna sesja powtarza dokładnie te same cele (bez cofania się, ale też bez postępu).',
    'config.incrementSchemeRepRange': 'Cel powt.',
    'config.incrementSchemeModeAllSets': 'Dodawaj powtórzenie do każdej serii co sesję',
    'config.incrementSchemeModeOneTotalRep': 'Dodawaj jedno powtórzenie łącznie co sesję',
    'config.repGoalTitle': 'System celu powtórzeń',
    'config.repGoalDescription':
      'System celu powtórzeń: zamiast stałego celu na serię, każdą serię roboczą wykonujesz blisko odmowy mięśniowej i zapisujesz swobodnie. Powtórzenia ze wszystkich serii roboczych są sumowane na koniec sesji (np. 8+8+6+6 = 28) i porównywane z łącznym celem powtórzeń. Jeśli przekroczysz cel, ciężar rośnie w kolejnej sesji; jeśli go nie osiągniesz, ciężar pozostaje taki sam, byś mógł spróbować ponownie.',
    'config.repGoalTotalRepGoalLabel': 'Cel powtórzeń',
    'config.waveProgressionTitle': 'Progresja falowa',
    'config.waveProgressionDescription':
      'Progresja falowa: wszystkie serie robocze mają zawsze ten sam cel powtórzeń i ten sam ciężar - w przeciwieństwie do podwójnej progresji nie ma zróżnicowania między seriami.\n\nPrzykład z Powtórzeniami początkowymi 8, Powtórzeniami końcowymi 6, Redukcją powtórzeń 1, ciężarem startowym 100 kg:\nSesja 1: 3x8 @100 kg\nUdało się → Sesja 2: 3x7 @101 kg\nUdało się → Sesja 3: 3x6 @102 kg (osiągnięto powtórzenia końcowe)\nUdało się → nowa fala, Sesja 4: 3x8 @101 kg (jeden przyrost powyżej miejsca, w którym zaczęła się POPRZEDNIA fala, nie tam, gdzie się skończyła)\nUdało się → Sesja 5: 3x7 @102 kg\nUdało się → Sesja 6: 3x6 @103 kg\nUdało się → Sesja 7: 3x8 @102 kg (kolejna fala)\n\nSens tego: każda pełna fala podnosi własny ciężar startowy fali o jeden przyrost, podczas gdy w obrębie fali ciężar na chwilę rośnie wyżej kosztem mniejszej liczby powtórzeń, zamiast za każdym razem wracać całkowicie do początku.\n\nKażda pojedyncza seria robocza musi osiągnąć co najmniej aktualny cel powtórzeń - jeśli choć jedna seria go nie osiągnie, cała sesja liczy się jako nieudana: ciężar i cel powtórzeń pozostają dokładnie takie same, a kolejna sesja powtarza tę samą próbę.',
    'config.waveProgressionInitialRepsLabel': 'Powtórzenia początkowe',
    'config.waveProgressionFinalRepsLabel': 'Powtórzenia końcowe',
    'config.waveProgressionDecrementLabel': 'Redukcja powtórzeń na sesję',
    'config.restsTitle': 'Przerwy',
    'config.restsOverrideHint': 'Te wartości obowiązują jako domyślne dla wszystkich ćwiczeń i mogą być indywidualnie nadpisane w ćwiczeniach planów i jednostek treningowych.',
    'config.firstRestAfterSetLabel': '1. przerwa',
    'config.firstRestAfterSetTooltip': 'Czas oczekiwania po zakończeniu serii do pierwszego gongu przypominającego.',
    'config.secondRestAfterSetLabel': '2. przerwa',
    'config.secondRestAfterSetTooltip': 'Czas oczekiwania po zakończeniu serii do drugiego gongu – liczony od tego samego momentu, a nie dodatkowo. Wartość ≤ 1. przerwie: tylko jeden gong.',
    'config.restBetweenExercisesLabel': 'Przerwa między ćwiczeniami',
    'config.autoTrainingSessionTitle': 'Zautomatyzowana jednostka treningowa',
    'config.autoTrainingSessionHint':
      'Określa, co się dzieje, gdy wszystkie serie w sekcji są zakończone: czy nastąpi automatyczne przejście do następnej sekcji z niedokończonymi seriami - w razie potrzeby nawet do następnego ćwiczenia.',
    'config.warmupSetsAutoAdvanceLabel': 'Serie rozgrzewkowe',
