    'config.autoAdvanceOffOption': 'Brak automatyzacji',
    'sessions.autoAdvanceToWorkingQuestion': 'Wszystkie serie rozgrzewkowe są zakończone. Przejść do serii roboczych?',
    'sessions.autoAdvanceToCooldownQuestion': 'Wszystkie serie robocze są zakończone. Przejść do serii wyciszających?',
    'sessions.autoAdvanceWarmupToCooldownQuestion': 'Wszystkie serie rozgrzewkowe są zakończone. Przejść do serii wyciszających?',
    'sessions.autoAdvanceToNextExerciseQuestion': 'Wszystkie serie tutaj są zakończone. Przejść do następnego ćwiczenia?',
    'config.linearProgressionTitle': 'Progresja liniowa',
    'config.linearProgressionDescription':
      'Progresja liniowa: klasyczny styl StrongLifts/Starting Strength. Każda seria robocza musi osiągnąć własną, stałą minimalną liczbę powtórzeń (zwykle taką samą dla wszystkich serii, np. 3x5, ale ustawianą osobno dla każdej serii), aby ciężar wzrósł w kolejnej sesji; jeśli nie uda się choćby jedna seria, ten sam ciężar powtarza się, byś mógł spróbować ponownie. W przeciwieństwie do pozostałych schematów, tutaj nie ma globalnego ustawienia domyślnego – minimalna liczba powtórzeń jest ustawiana bezpośrednio dla każdego ćwiczenia w planie treningowym. To domyślny schemat progresji dla nowo dodanych ćwiczeń.',

