    'config.plateQuantity': 'Db',
    'config.plateDuplicateError': 'Már létezik súlytárcsa ezzel a súllyal és átmérővel.',
    'config.doubleProgressionTitle': 'Dupla progresszió',
    'config.incrementSchemeDescription':
      'Dupla progresszió: két különböző progressziós mód ugyanahhoz az elvhez. Példa 8-10-es ismétlésszám-tartománnyal.\n\n„Ismétlés hozzáadása minden szetthez" mód (egyszerűbb):\n1. edzés: 3x8 (minden szett 8 ismétlés)\nSikerült → 2. edzés: 3x9\nSikerült → 3. edzés: 3x10 (elérted a felső határt)\nSikerült → a súly nő, vissza 3x8-ra az új súllyal\n\n„Összesen egy ismétlés hozzáadása" mód (finomabb, példa 4 szettel):\n1. edzés: 4x8\nSikerült → 2. edzés: 1x9 + 3x8 (csak egy szett kapja az extra ismétlést, nem mindegyik egyszerre)\nSikerült → 3. edzés: 2x9 + 2x8\nSikerült → 4. edzés: 3x9 + 1x8\nSikerült → 5. edzés: 4x9 (most már mindegyik elérte a 9-et)\nSikerült → 6. edzés: 1x10 + 3x9\nSikerült → 7. edzés: 2x10 + 2x9\nSikerült → 8. edzés: 3x10 + 1x9\nSikerült → 9. edzés: 4x10 (elérted a felső határt)\nSikerült → a súly nő, vissza 4x8-ra\n\nEnnek a második módnak az értelme: a növekedés több edzésre oszlik el (4 szettnél egy teljes ciklus 9 edzésig tart, nem csak 3-ig), mert edzésenként csak egyetlen ismétlés adódik hozzá összesen, nem pedig egyszerre eggyel több minden szetthez.\n\nAz „Egy szett csak akkor számít, ha..." azt jelenti: minden egyes szettet a saját, aznapi célja alapján ellenőrzünk. Ha akár csak egy szett sem éri el a célját (pl. 2x9+2x8 esetén az egyik 9-es szett csak 8-at teljesít), az egész edzés sikertelennek számít - a következő edzés pontosan ugyanazokat a célokat ismétli meg (nincs visszalépés, de haladás sincs).',
    'config.incrementSchemeRepRange': 'Cél ism.',
    'config.incrementSchemeModeAllSets': 'Edzésenként egy ismétlés hozzáadása minden szetthez',
    'config.incrementSchemeModeOneTotalRep': 'Edzésenként összesen egy ismétlés hozzáadása',
    'config.repGoalTitle': 'Ismétléscél-rendszer',
    'config.repGoalDescription':
      'Ismétléscél-rendszer: szettenkénti rögzített cél helyett minden munkaszettet közel a kimerülésig végzel, és szabadon rögzíted az eredményt. Az összes munkaszett ismétlései az edzés végén összeadódnak (pl. 8+8+6+6 = 28), és összehasonlításra kerülnek az összesített ismétléscéllal. Ha meghaladod a célt, a következő edzésen nő a súly; ha nem éred el, a súly változatlan marad, hogy újra megpróbálhasd.',
    'config.repGoalTotalRepGoalLabel': 'Ismétléscél',
    'config.waveProgressionTitle': 'Hullám progresszió',
    'config.waveProgressionDescription':
      'Hullám progresszió: minden munkaszett mindig ugyanazt az ismétléscélt és súlyt osztja - a dupla progresszióval ellentétben itt nincs szettenkénti eltérés.\n\nPélda: Kezdő ismétlésszám 8, Végső ismétlésszám 6, Ismétlésszám csökkentése 1, kezdő súly 100 kg:\n1. edzés: 3x8 @100 kg\nSikerült → 2. edzés: 3x7 @101 kg\nSikerült → 3. edzés: 3x6 @102 kg (elérted a végső ismétlésszámot)\nSikerült → új hullám, 4. edzés: 3x8 @101 kg (egy növekménnyel az ELŐZŐ hullám kezdete fölött, nem ott, ahol véget ért)\nSikerült → 5. edzés: 3x7 @102 kg\nSikerült → 6. edzés: 3x6 @103 kg\nSikerült → 7. edzés: 3x8 @102 kg (következő hullám)\n\nEnnek az értelme: minden teljes hullám egy növekménnyel emeli a hullám saját kezdő súlyát, miközben egy hullámon belül a súly egy időre magasabbra megy kevesebb ismétlés árán, ahelyett hogy minden alkalommal teljesen visszaesne.\n\nMinden egyes munkaszettnek el kell érnie legalább az aktuális ismétléscélt - ha akár csak egy szett sem éri el, az egész edzés sikertelennek számít: a súly és az ismétléscél pontosan ugyanaz marad, a következő edzés pedig megismétli ugyanazt a próbálkozást.',
    'config.waveProgressionInitialRepsLabel': 'Kezdő ismétlésszám',
    'config.waveProgressionFinalRepsLabel': 'Végső ismétlésszám',
    'config.waveProgressionDecrementLabel': 'Ismétlésszám csökkentése edzésenként',
    'config.restsTitle': 'Szünetek',
    'config.restsOverrideHint': 'Ezek az értékek alapértelmezettként érvényesek minden gyakorlatra, és egyénileg felülírhatók az edzéstervek és edzések gyakorlatainál.',
    'config.firstRestAfterSetLabel': '1. szünet',
