    'sessions.autoAdvanceToWorkingQuestion': 'Minden bemelegítő sorozat kész. Váltás a munkasorozatokra?',
    'sessions.autoAdvanceToCooldownQuestion': 'Minden munkasorozat kész. Váltás a levezető sorozatokra?',
    'sessions.autoAdvanceWarmupToCooldownQuestion': 'Minden bemelegítő sorozat kész. Váltás a levezető sorozatokra?',
    'sessions.autoAdvanceToNextExerciseQuestion': 'Minden sorozat itt kész. Váltás a következő gyakorlatra?',
    'config.linearProgressionTitle': 'Lineáris progresszió',
    'config.linearProgressionDescription':
      'Lineáris progresszió: a klasszikus StrongLifts/Starting Strength stílus. Minden munkaszettnek el kell érnie a saját rögzített minimális ismétlésszámát (általában minden szettnél azonos, pl. 3x5, de szettenként külön is beállítható), hogy a súly nőjön a következő edzésen; ha akár egy szettet is elrontasz, ugyanaz a súly ismétlődik, hogy újra megpróbálhasd. A többi sémától eltérően itt nincs globális alapbeállítás – a minimális ismétlésszámot közvetlenül az egyes gyakorlatoknál állítod be az edzéstervben. Ez az alapértelmezett progressziós séma az újonnan hozzáadott gyakorlatokhoz.',

