    'trainingPlans.weightIncrementLabel': 'Vægtstigning',
    'trainingPlans.weightIncrementTooltip': 'Hvor meget vægt (eller, afhængigt af typen valgt til højre, hvilken procentdel) der tilføjes efter en vellykket session. Tilsidesætter standardstigningen (1).',
