    'config.doubleProgressionTitle': 'Dobbelt progression',
    'config.incrementSchemeDescription': 'Dobbelt progression: to forskellige progressionstilstande for samme princip. Eksempel med et rep-interval på 8-10.\n\nTilstanden "Tilføj en rep til hvert sæt" (enklere):\nSession 1: 3x8 (hvert sæt 8 reps)\nSucces → Session 2: 3x9\nSucces → Session 3: 3x10 (toppen af intervallet nået)\nSucces → vægten stiger, tilbage til 3x8 med den nye vægt\n\nTilstanden "Tilføj én ekstra rep i alt" (mildere, eksempel med 4 sæt):\nSession 1: 4x8\nSucces → Session 2: 1x9 + 3x8 (kun ét sæt får den ekstra rep, ikke alle på én gang)\nSucces → Session 3: 2x9 + 2x8\nSucces → Session 4: 3x9 + 1x8\nSucces → Session 5: 4x9 (hvert sæt har nu indhentet 9)\nSucces → Session 6: 1x10 + 3x9\nSucces → Session 7: 2x10 + 2x9\nSucces → Session 8: 3x10 + 1x9\nSucces → Session 9: 4x10 (toppen af intervallet nået)\nSucces → vægten stiger, tilbage til 4x8\n\nPointen med denne anden tilstand: stigningen spredes over flere sessioner (med 4 sæt tager en fuld cyklus 9 sessioner i stedet for blot 3), da kun én samlet rep tilføjes pr. session i stedet for én mere på hvert sæt på én gang.\n\n"Et sæt tæller kun én gang..." betyder: hvert enkelt sæt tjekkes mod sit eget mål for den session. Hvis blot ét sæt misser sit mål (f.eks. i 2x9+2x8, hvor et af 9-reps-sættene kun klarer 8), tæller hele sessionen som mislykket - næste session gentager præcis de samme mål (intet skridt tilbage, men heller ingen fremgang).',
    'config.incrementSchemeRepRange': 'Mål-reps',
    'config.incrementSchemeModeAllSets': 'Tilføj en rep til hvert sæt hver session',
    'config.incrementSchemeModeOneTotalRep': 'Tilføj én ekstra rep i alt hver session',
    'config.repGoalTitle': 'Rep-målsystem',
    'config.repGoalDescription': 'Rep-målsystem: i stedet for et fast mål pr. sæt presses hvert arbejdssæt tæt på udmattelse og logges frit. Reps fra alle arbejdssæt lægges sammen ved sessionens afslutning (f.eks. 8+8+6+6 = 28) og sammenlignes med det samlede repmål. Overgår du målet, stiger vægten næste session; kommer du til kort, gentages samme vægt, så du kan prøve igen.',
    'config.repGoalTotalRepGoalLabel': 'Repmål',
    'config.waveProgressionTitle': 'Bølgeprogression',
    'config.waveProgressionDescription': 'Bølgeprogression: hvert arbejdssæt har altid samme repmål og vægt - i modsætning til dobbelt progression er der ingen variation pr. sæt.\n\nEksempel med indledende reps 8, afsluttende reps 6, rep-nedtælling 1, startvægt 100 kg:\nSession 1: 3x8 @100 kg\nSucces → Session 2: 3x7 @101 kg\nSucces → Session 3: 3x6 @102 kg (afsluttende reps nået)\nSucces → ny bølge, Session 4: 3x8 @101 kg (ét trin over der, hvor den FORRIGE bølge startede, ikke der hvor den sluttede)\nSucces → Session 5: 3x7 @102 kg\nSucces → Session 6: 3x6 @103 kg\nSucces → Session 7: 3x8 @102 kg (næste bølge)\n\nPointen: hver fulde bølge hæver bølgens egen startvægt med ét trin, mens vægten inden for en bølge stiger et stykke tid på bekostning af færre reps, i stedet for at blive nulstillet helt ned hver gang.\n\nHvert enkelt arbejdssæt skal nå mindst det aktuelle repmål - hvis blot ét sæt ikke gør det, tæller hele sessionen som mislykket: vægt og repmål forbliver præcis de samme, og næste session gentager præcis samme forsøg.',
    'config.waveProgressionInitialRepsLabel': 'Indledende reps',
    'config.waveProgressionFinalRepsLabel': 'Afsluttende reps',
    'config.waveProgressionDecrementLabel': 'Rep-nedtælling pr. session',
    'config.restsTitle': 'Pauser',
    'config.restsOverrideHint': 'Disse værdier gælder som standard for hver øvelse og kan tilsidesættes individuelt i øvelserne i træningsplaner og træningssessioner.',
    'config.firstRestAfterSetLabel': '1. pause',
    'config.firstRestAfterSetTooltip': 'Ventetid efter et sæt, indtil den første påmindelsesgong.',
    'config.secondRestAfterSetLabel': '2. pause',
    'config.secondRestAfterSetTooltip': 'Ventetid efter et sæt, indtil den anden gong – talt fra samme tidspunkt, ikke oveni. Værdi ≤ 1. pause: kun én gong.',
    'config.restBetweenExercisesLabel': 'Pause mellem øvelser',
    'config.autoTrainingSessionTitle': 'Automatiseret træningssession',
    'config.autoTrainingSessionHint': 'Styrer, hvad der sker, når hvert sæt i en sektion er gennemført: om der automatisk skiftes til den næste sektion, der stadig har åbne sæt - om nødvendigt endda den næste øvelse.',
    'config.warmupSetsAutoAdvanceLabel': 'Opvarmningssæt',
    'config.workingSetsAutoAdvanceLabel': 'Arbejdssæt',
    'config.autoAdvanceImmediateOption': 'Gå videre straks efter det sidste sæt',
    'config.autoAdvanceConfirmOption': 'Spørg først',
    'config.autoAdvanceOffOption': 'Ingen automatik',
    'sessions.autoAdvanceToWorkingQuestion': 'Alle opvarmningssæt er gennemført. Skift til arbejdssættene?',
    'sessions.autoAdvanceToCooldownQuestion': 'Alle arbejdssæt er gennemført. Skift til nedkølingen?',
    'sessions.autoAdvanceWarmupToCooldownQuestion': 'Alle opvarmningssæt er gennemført. Skift til nedkølingen?',
    'sessions.autoAdvanceToNextExerciseQuestion': 'Alle sæt her er gennemført. Skift til næste øvelse?',
    'config.linearProgressionTitle': 'Lineær progression',
    'config.linearProgressionDescription': 'Lineær progression: den klassiske StrongLifts/Starting Strength-stil. Hvert arbejdssæt skal nå sit eget faste minimumsantal reps (som regel det samme på tværs af sæt, f.eks. 3x5, men justerbart pr. sæt), for at vægten stiger næste session; misser du blot ét sæt, gentages samme vægt, så du kan prøve igen. I modsætning til de andre skemaer her er der ingen global standard at konfigurere - minimumsantallet af reps angives direkte på hver øvelse i dens træningsplan. Dette er standard-progressionsskemaet for nyoprettede øvelser.',
