    'config.incrementSchemeDescription':
      'Dobbel progresjon: to forskjellige progresjonsmodi for samme prinsipp. Eksempel med et repsintervall på 8-10.\n\nModus "Legg til en rep på hvert sett" (enklere):\nØkt 1: 3x8 (hvert sett 8 reps)\nSuksess → Økt 2: 3x9\nSuksess → Økt 3: 3x10 (toppen av intervallet nådd)\nSuksess → vekten går opp, tilbake til 3x8 med den nye vekten\n\nModus "Legg til én ekstra rep totalt" (mildere, eksempel med 4 sett):\nØkt 1: 4x8\nSuksess → Økt 2: 1x9 + 3x8 (kun ett sett får den ekstra repen, ikke alle på én gang)\nSuksess → Økt 3: 2x9 + 2x8\nSuksess → Økt 4: 3x9 + 1x8\nSuksess → Økt 5: 4x9 (hvert sett har nå tatt igjen til 9)\nSuksess → Økt 6: 1x10 + 3x9\nSuksess → Økt 7: 2x10 + 2x9\nSuksess → Økt 8: 3x10 + 1x9\nSuksess → Økt 9: 4x10 (toppen av intervallet nådd)\nSuksess → vekten går opp, tilbake til 4x8\n\nPoenget med denne andre modusen: økningen fordeles over flere økter (med 4 sett tar en full syklus 9 økter i stedet for bare 3), siden kun én total rep legges til hver økt i stedet for én ekstra på hvert sett samtidig.\n\n"Et sett teller bare én gang..." betyr: hvert enkelt sett sjekkes mot sitt eget mål for den økten. Hvis selv ett sett bommer på målet (f.eks. i 2x9+2x8, klarer et av 9-reps-settene bare 8), telles hele økten som mislykket - neste økt gjentar nøyaktig de samme målene (ingen tilbakegang, men heller ingen fremgang).',
    'config.incrementSchemeRepRange': 'Mål reps',
    'config.incrementSchemeModeAllSets': 'Legg til en rep på hvert sett hver økt',
    'config.incrementSchemeModeOneTotalRep': 'Legg til én ekstra rep totalt hver økt',
    'config.repGoalTitle': 'Repsmål-system',
    'config.repGoalDescription':
      'Repsmål-system: i stedet for et fast mål per sett, presses hvert arbeidssett nær utmattelse og logges fritt. Reps fra alle arbeidssett legges sammen ved slutten av økten (f.eks. 8+8+6+6 = 28) og sammenlignes med det totale repsmålet. Overgår du målet går vekten opp neste økt; når du det ikke, gjentas samme vekt slik at du kan prøve igjen.',
    'config.repGoalTotalRepGoalLabel': 'Repsmål',
    'config.waveProgressionTitle': 'Bølgeprogresjon',
    'config.waveProgressionDescription':
      'Bølgeprogresjon: hvert arbeidssett har alltid samme repsmål og vekt - i motsetning til dobbel progresjon er det ingen variasjon per sett.\n\nEksempel med startreps 8, sluttreps 6, repsreduksjon 1, startvekt 100 kg:\nØkt 1: 3x8 @100 kg\nSuksess → Økt 2: 3x7 @101 kg\nSuksess → Økt 3: 3x6 @102 kg (sluttreps nådd)\nSuksess → ny bølge, Økt 4: 3x8 @101 kg (én økning over der den FORRIGE bølgen startet, ikke der den endte)\nSuksess → Økt 5: 3x7 @102 kg\nSuksess → Økt 6: 3x6 @103 kg\nSuksess → Økt 7: 3x8 @102 kg (neste bølge)\n\nPoenget: hver fullførte bølge hever bølgens egen startvekt med én økning, mens vekten innad i en bølge klatrer høyere en stund på bekostning av færre reps, i stedet for å nullstilles helt hver gang.\n\nHvert enkelt arbeidssett må nå minst det gjeldende repsmålet - hvis selv ett sett bommer på det, telles hele økten som mislykket: vekt og repsmål forblir helt uendret, og neste økt gjentar nøyaktig samme forsøk.',
    'config.waveProgressionInitialRepsLabel': 'Startreps',
    'config.waveProgressionFinalRepsLabel': 'Sluttreps',
    'config.waveProgressionDecrementLabel': 'Repsreduksjon per økt',
    'config.restsTitle': 'Pauser',
    'config.restsOverrideHint': 'Disse verdiene gjelder som standard for alle øvelser, og kan overstyres individuelt i øvelsene i treningsplaner og treningsøkter.',
    'config.firstRestAfterSetLabel': '1. pause',
    'config.firstRestAfterSetTooltip': 'Ventetid etter et sett til den første påminnelsesgongen.',
    'config.secondRestAfterSetLabel': '2. pause',
    'config.secondRestAfterSetTooltip': 'Ventetid etter et sett til den andre gongen – regnet fra samme tidspunkt, ikke i tillegg. Verdi ≤ 1. pause: bare én gong.',
    'config.restBetweenExercisesLabel': 'Pause mellom øvelser',
    'config.autoTrainingSessionTitle': 'Automatisert treningsøkt',
    'config.autoTrainingSessionHint':
      'Styrer hva som skjer når alle sett i en seksjon er fullført: om det automatisk bytter til neste seksjon som fortsatt har åpne sett - om nødvendig, selv neste øvelse.',
    'config.warmupSetsAutoAdvanceLabel': 'Oppvarmingssett',
    'config.workingSetsAutoAdvanceLabel': 'Arbeidssett',
    'config.autoAdvanceImmediateOption': 'Gå videre rett etter siste sett',
    'config.autoAdvanceConfirmOption': 'Spør først',
    'config.autoAdvanceOffOption': 'Ingen automatikk',
    'sessions.autoAdvanceToWorkingQuestion': 'Alle oppvarmingssett er fullført. Bytte til arbeidssettene?',
    'sessions.autoAdvanceToCooldownQuestion': 'Alle arbeidssett er fullført. Bytte til nedtrapping?',
    'sessions.autoAdvanceWarmupToCooldownQuestion': 'Alle oppvarmingssett er fullført. Bytte til nedtrapping?',
    'sessions.autoAdvanceToNextExerciseQuestion': 'Alle sett her er fullført. Bytte til neste øvelse?',
    'config.linearProgressionTitle': 'Lineær progresjon',
    'config.linearProgressionDescription':
      'Lineær progresjon: den klassiske StrongLifts/Starting Strength-stilen. Hvert arbeidssett må nå sitt eget faste minimum av reps (vanligvis likt på tvers av sett, f.eks. 3x5, men justerbart per sett) for at vekten skal øke neste økt; bommer du på selv ett sett, gjentas samme vekt slik at du kan prøve igjen. I motsetning til de andre skjemaene her finnes det ingen global standard å konfigurere - minimum antall reps settes direkte på hver øvelse i treningsplanen. Dette er standard progresjonsskjema for nylig lagte øvelser.',

