    'config.plateDuplicateError': 'En viktskiva med denna vikt och diameter finns redan.',
    'config.doubleProgressionTitle': 'Dubbel progression',
    'config.incrementSchemeDescription':
      'Dubbel progression: två olika progressionslägen för samma princip. Exempel med ett repetitionsintervall på 8-10.\n\nLäge "Lägg till en repetition på varje set" (enklare):\nPass 1: 3x8 (varje set 8 repetitioner)\nLyckat → Pass 2: 3x9\nLyckat → Pass 3: 3x10 (toppen av intervallet nådd)\nLyckat → vikten höjs, tillbaka till 3x8 med den nya vikten\n\nLäge "Lägg till en extra repetition totalt" (mildare, exempel med 4 set):\nPass 1: 4x8\nLyckat → Pass 2: 1x9 + 3x8 (endast ett set får den extra repetitionen, inte alla på en gång)\nLyckat → Pass 3: 2x9 + 2x8\nLyckat → Pass 4: 3x9 + 1x8\nLyckat → Pass 5: 4x9 (varje set har nu kommit ikapp till 9)\nLyckat → Pass 6: 1x10 + 3x9\nLyckat → Pass 7: 2x10 + 2x9\nLyckat → Pass 8: 3x10 + 1x9\nLyckat → Pass 9: 4x10 (toppen av intervallet nådd)\nLyckat → vikten höjs, tillbaka till 4x8\n\nPoängen med detta andra läge: ökningen sprids över fler pass (med 4 set tar en full cykel 9 pass istället för bara 3), eftersom endast en enda repetition totalt läggs till varje pass istället för en till på varje set samtidigt.\n\n"Ett set räknas bara en gång..." betyder: varje enskilt set kontrolleras mot sitt eget mål för det passet. Om även bara ett set missar sitt mål (t.ex. i 2x9+2x8 klarar ett av 9-repetitionsseten bara 8), räknas hela passet som misslyckat - nästa pass upprepar exakt samma mål (inget steg tillbaka, men inget framsteg heller).',
    'config.incrementSchemeRepRange': 'Målreps',
    'config.incrementSchemeModeAllSets': 'Lägg till en repetition på varje set varje pass',
    'config.incrementSchemeModeOneTotalRep': 'Lägg till en extra repetition totalt varje pass',
    'config.repGoalTitle': 'Repetitionsmålsystem',
    'config.repGoalDescription':
      'Repetitionsmålsystem: istället för ett fast mål per set körs varje arbetsset nära felslag och loggas fritt. Repetitionerna från alla arbetsset summeras i slutet av passet (t.ex. 8+8+6+6 = 28) och jämförs med det totala repetitionsmålet. Överträffar du målet höjs vikten nästa pass; når du inte upp upprepas samma vikt så att du kan försöka igen.',
    'config.repGoalTotalRepGoalLabel': 'Repetitionsmål',
    'config.waveProgressionTitle': 'Vågprogression',
    'config.waveProgressionDescription':
      'Vågprogression: varje arbetsset delar alltid samma repetitionsmål och vikt - till skillnad från dubbel progression finns ingen variation per set.\n\nExempel med Initiala repetitioner 8, Slutliga repetitioner 6, Repetitionsminskning 1, startvikt 100 kg:\nPass 1: 3x8 @100 kg\nLyckat → Pass 2: 3x7 @101 kg\nLyckat → Pass 3: 3x6 @102 kg (slutliga repetitioner nådda)\nLyckat → ny våg, Pass 4: 3x8 @101 kg (ett steg över där den FÖREGÅENDE vågen startade, inte där den slutade)\nLyckat → Pass 5: 3x7 @102 kg\nLyckat → Pass 6: 3x6 @103 kg\nLyckat → Pass 7: 3x8 @102 kg (nästa våg)\n\nPoängen: varje fullständig våg höjer vågens egen startvikt med ett steg, medan vikten inom en våg klättrar högre ett tag på bekostnad av färre repetitioner, istället för att återställas hela vägen ner varje gång.\n\nVarje enskilt arbetsset måste nå åtminstone det aktuella repetitionsmålet - om även bara ett set missar det räknas hela passet som misslyckat: vikt och repetitionsmål förblir exakt desamma, och nästa pass upprepar identiskt samma försök.',
    'config.waveProgressionInitialRepsLabel': 'Initiala repetitioner',
    'config.waveProgressionFinalRepsLabel': 'Slutliga repetitioner',
    'config.waveProgressionDecrementLabel': 'Repetitionsminskning per pass',
    'config.restsTitle': 'Vilor',
    'config.restsOverrideHint': 'Dessa värden gäller som standard för varje övning, och kan åsidosättas individuellt i övningarna i träningsprogram och träningspass.',
    'config.firstRestAfterSetLabel': '1:a vilan',
    'config.firstRestAfterSetTooltip': 'Väntetid efter ett set tills den första påminnelsegongen.',
    'config.secondRestAfterSetLabel': '2:a vilan',
