    'trainingPlans.weightIncrementLabel': 'Painon lisäys',
    'trainingPlans.weightIncrementTooltip': 'Kuinka paljon painoa (tai oikealla valitusta tyypistä riippuen kuinka monta prosenttia) lisätään onnistuneen harjoituksen jälkeen. Ohittaa oletuslisäyksen (1).',
