    'config.plateDuplicateError': 'Tällä painolla ja halkaisijalla on jo levy olemassa.',
    'config.doubleProgressionTitle': 'Kaksoisprogressio',
    'config.incrementSchemeDescription': 'Kaksoisprogressio: kaksi eri progressiotapaa samalle periaatteelle. Esimerkki toistoalueella 8-10.\n\n"Lisää toisto jokaiseen sarjaan" -tapa (yksinkertaisempi):\nHarjoitus 1: 3x8 (jokainen sarja 8 toistoa)\nOnnistui → Harjoitus 2: 3x9\nOnnistui → Harjoitus 3: 3x10 (alueen yläraja saavutettu)\nOnnistui → paino nousee, takaisin 3x8 uudella painolla\n\n"Lisää yksi ylimääräinen toisto yhteensä" -tapa (lempeämpi, esimerkki 4 sarjalla):\nHarjoitus 1: 4x8\nOnnistui → Harjoitus 2: 1x9 + 3x8 (vain yksi sarja saa ylimääräisen toiston, ei kaikki kerralla)\nOnnistui → Harjoitus 3: 2x9 + 2x8\nOnnistui → Harjoitus 4: 3x9 + 1x8\nOnnistui → Harjoitus 5: 4x9 (jokainen sarja on nyt saavuttanut 9:n)\nOnnistui → Harjoitus 6: 1x10 + 3x9\nOnnistui → Harjoitus 7: 2x10 + 2x9\nOnnistui → Harjoitus 8: 3x10 + 1x9\nOnnistui → Harjoitus 9: 4x10 (alueen yläraja saavutettu)\nOnnistui → paino nousee, takaisin 4x8\n\nTämän toisen tavan tarkoitus: lisäys jakautuu useammalle harjoitukselle (4 sarjalla täysi kierros kestää 9 harjoitusta vain 3:n sijaan), koska joka harjoituksessa lisätään vain yksi toisto yhteensä sen sijaan, että jokaiseen sarjaan lisättäisiin yksi kerralla.\n\n"Sarja lasketaan vain kerran..." tarkoittaa: jokaista yksittäistä sarjaa verrataan sen omaan tavoitteeseen kyseisessä harjoituksessa. Jos yksikin sarja jää tavoitteestaan (esim. kohdassa 2x9+2x8 toinen 9 toiston sarjoista jää 8:aan), koko harjoitus lasketaan epäonnistuneeksi - seuraava harjoitus toistaa täsmälleen samat tavoitteet (ei askelta taaksepäin, mutta ei edistystäkään).',
    'config.incrementSchemeRepRange': 'Tavoitetoistot',
    'config.incrementSchemeModeAllSets': 'Lisää toisto jokaiseen sarjaan joka harjoituksessa',
    'config.incrementSchemeModeOneTotalRep': 'Lisää yksi ylimääräinen toisto yhteensä joka harjoituksessa',
    'config.repGoalTitle': 'Toistotavoitejärjestelmä',
    'config.repGoalDescription': 'Toistotavoitejärjestelmä: kiinteän sarjakohtaisen tavoitteen sijaan jokainen työsarja viedään lähelle väsymystä ja kirjataan vapaasti. Kaikkien työsarjojen toistot lasketaan yhteen harjoituksen lopussa (esim. 8+8+6+6 = 28) ja verrataan kokonaistoistotavoitteeseen. Jos tavoite ylitetään, paino nousee seuraavassa harjoituksessa; jos se jää alle, sama paino toistuu, jotta voit yrittää uudelleen.',
    'config.repGoalTotalRepGoalLabel': 'Toistotavoite',
    'config.waveProgressionTitle': 'Aaltoprogressio',
    'config.waveProgressionDescription': 'Aaltoprogressio: jokaisella työsarjalla on aina sama toistotavoite ja paino - toisin kuin kaksoisprogressiossa, sarjakohtaista vaihtelua ei ole.\n\nEsimerkki, kun alkutoistot 8, lopputoistot 6, toistojen vähennys 1, aloituspaino 100 kg:\nHarjoitus 1: 3x8 @100 kg\nOnnistui → Harjoitus 2: 3x7 @101 kg\nOnnistui → Harjoitus 3: 3x6 @102 kg (lopputoistot saavutettu)\nOnnistui → uusi aalto, Harjoitus 4: 3x8 @101 kg (yksi lisäys sen yläpuolella, mistä EDELLINEN aalto alkoi, ei mihin se päättyi)\nOnnistui → Harjoitus 5: 3x7 @102 kg\nOnnistui → Harjoitus 6: 3x6 @103 kg\nOnnistui → Harjoitus 7: 3x8 @102 kg (seuraava aalto)\n\nIdea: jokainen täysi aalto nostaa aallon omaa aloituspainoa yhdellä lisäyksellä, kun taas aallon sisällä paino nousee hetkeksi korkeammalle vähempien toistojen kustannuksella, sen sijaan että se nollautuisi joka kerta täysin takaisin alas.\n\nJokaisen yksittäisen työsarjan on saavutettava vähintään nykyinen toistotavoite - jos yksikin sarja jää siitä, koko harjoitus lasketaan epäonnistuneeksi: paino ja toistotavoite pysyvät täsmälleen samoina, ja seuraava harjoitus toistaa identtisen yrityksen.',
    'config.waveProgressionInitialRepsLabel': 'Alkutoistot',
    'config.waveProgressionFinalRepsLabel': 'Lopputoistot',
    'config.waveProgressionDecrementLabel': 'Toistojen vähennys per harjoitus',
    'config.restsTitle': 'Lepoajat',
    'config.restsOverrideHint': 'Nämä arvot toimivat oletuksena jokaiselle liikkeelle, ja ne voidaan ohittaa yksilöllisesti harjoitusohjelmien ja harjoitusten liikkeissä.',
    'config.firstRestAfterSetLabel': '1. lepo',
    'config.firstRestAfterSetTooltip': 'Odotusaika sarjan jälkeen ensimmäiseen muistutusgongiin asti.',
    'config.secondRestAfterSetLabel': '2. lepo',
    'config.secondRestAfterSetTooltip': 'Odotusaika sarjan jälkeen toiseen gongiin asti – laskettuna samasta hetkestä, ei päälle. Arvo ≤ 1. lepo: vain yksi gong.',
    'config.restBetweenExercisesLabel': 'Lepo liikkeiden välillä',
    'config.autoTrainingSessionTitle': 'Automatisoitu harjoitus',
    'config.autoTrainingSessionHint': 'Määrittää, mitä tapahtuu, kun kaikki osion sarjat on tehty: siirrytäänkö automaattisesti seuraavaan osioon, jossa on vielä avoimia sarjoja - tarvittaessa jopa seuraavaan liikkeeseen.',
    'config.warmupSetsAutoAdvanceLabel': 'Alkuverryttelysarjat',
    'config.workingSetsAutoAdvanceLabel': 'Työsarjat',
    'config.autoAdvanceImmediateOption': 'Siirry heti viimeisen sarjan jälkeen',
