    'config.autoAdvanceOffOption': 'Ei automaatiota',
    'sessions.autoAdvanceToWorkingQuestion': 'Kaikki alkuverryttelysarjat on tehty. Siirrytäänkö työsarjoihin?',
    'sessions.autoAdvanceToCooldownQuestion': 'Kaikki työsarjat on tehty. Siirrytäänkö loppuverryttelyyn?',
    'sessions.autoAdvanceWarmupToCooldownQuestion': 'Kaikki alkuverryttelysarjat on tehty. Siirrytäänkö loppuverryttelyyn?',
    'sessions.autoAdvanceToNextExerciseQuestion': 'Kaikki tämän liikkeen sarjat on tehty. Siirrytäänkö seuraavaan liikkeeseen?',
    'config.linearProgressionTitle': 'Lineaarinen progressio',
    'config.linearProgressionDescription': 'Lineaarinen progressio: klassinen StrongLifts/Starting Strength -tyyli. Jokaisen työsarjan on saavutettava oma kiinteä vähimmäistoistomäärä (yleensä sama kaikissa sarjoissa, esim. 3x5, mutta säädettävissä sarjakohtaisesti), jotta paino nousisi seuraavassa harjoituksessa; jos yksikin sarja jää alle, sama paino toistuu, jotta voit yrittää uudelleen. Toisin kuin muissa tässä olevissa malleissa, tälle ei ole yleistä oletusasetusta - vähimmäistoistomäärä asetetaan suoraan kunkin liikkeen kohdalle sen harjoitusohjelmassa. Tämä on oletusprogressiomalli äskettäin lisätyille liikkeille.',
