    'config.dumbbellEmpty': 'Zatím žádné záznamy.',
    'config.dumbbellDeleteConfirm': 'Opravdu smazat tento záznam?',
    'config.dumbbellDuplicateError': 'Jednoruční činka s tímto názvem, váhou a průměrem už existuje.',
    'config.plateQuantity': 'Počet',
    'config.plateDuplicateError': 'Kotouč s touto váhou a průměrem už existuje.',
    'config.doubleProgressionTitle': 'Dvojitá progrese',
    'config.incrementSchemeDescription': 'Dvojitá progrese: dva různé režimy progrese pro stejný princip. Příklad s rozsahem opakování 8-10.\n\nRežim "Přidat opakování do každé série" (jednodušší):\nJednotka 1: 3x8 (každá série 8 opakování)\nÚspěch → Jednotka 2: 3x9\nÚspěch → Jednotka 3: 3x10 (dosažen horní konec rozsahu)\nÚspěch → váha se zvýší, zpět na 3x8 s novou váhou\n\nRežim "Přidat jedno opakování celkem navíc" (mírnější, příklad se 4 sériemi):\nJednotka 1: 4x8\nÚspěch → Jednotka 2: 1x9 + 3x8 (jen jedna série dostane opakování navíc, ne všechny najednou)\nÚspěch → Jednotka 3: 2x9 + 2x8\nÚspěch → Jednotka 4: 3x9 + 1x8\nÚspěch → Jednotka 5: 4x9 (každá série teď dohnala na 9)\nÚspěch → Jednotka 6: 1x10 + 3x9\nÚspěch → Jednotka 7: 2x10 + 2x9\nÚspěch → Jednotka 8: 3x10 + 1x9\nÚspěch → Jednotka 9: 4x10 (dosažen horní konec rozsahu)\nÚspěch → váha se zvýší, zpět na 4x8\n\nSmysl tohoto druhého režimu: zvýšení se rozloží do více jednotek (se 4 sériemi trvá celý cyklus 9 jednotek místo pouhých 3), protože se každou jednotku přidá jen jedno opakování celkem místo jednoho navíc v každé sérii najednou.\n\n"Série se počítá jen jednou..." znamená: každá jednotlivá série se posuzuje podle vlastního cíle pro danou jednotku. Pokud i jen jedna série nesplní svůj cíl (např. u 2x9+2x8 jedna ze sérií s 9 opakováními zvládne jen 8), celá jednotka se počítá jako neúspěšná - další jednotka opakuje přesně stejné cíle (žádný krok zpět, ale ani žádný pokrok).',
    'config.incrementSchemeRepRange': 'Cílová opakování',
    'config.incrementSchemeModeAllSets': 'Přidat opakování do každé série v každé jednotce',
    'config.incrementSchemeModeOneTotalRep': 'Přidat jedno opakování celkem navíc v každé jednotce',
    'config.repGoalTitle': 'Systém cílových opakování',
    'config.repGoalDescription': 'Systém cílových opakování: místo pevného cíle na sérii se každá pracovní série vede téměř do selhání a zapisuje se volně. Opakování ze všech pracovních sérií se na konci jednotky sečtou (např. 8+8+6+6 = 28) a porovnají s celkovým cílem opakování. Překonáš cíl a váha se příští jednotku zvýší; nedosáhneš ho a stejná váha se opakuje, abys to mohl zkusit znovu.',
    'config.repGoalTotalRepGoalLabel': 'Cíl opakování',
    'config.waveProgressionTitle': 'Vlnová progrese',
    'config.waveProgressionDescription': 'Vlnová progrese: každá pracovní série má vždy stejný cíl opakování a váhu - na rozdíl od dvojité progrese zde není žádná variace na úrovni série.\n\nPříklad s počátečními opakováními 8, konečnými opakováními 6, poklesem opakování 1, počáteční váhou 100 kg:\nJednotka 1: 3x8 @100 kg\nÚspěch → Jednotka 2: 3x7 @101 kg\nÚspěch → Jednotka 3: 3x6 @102 kg (dosaženo konečných opakování)\nÚspěch → nová vlna, Jednotka 4: 3x8 @101 kg (o jeden přírůstek nad tím, kde začala PŘEDCHOZÍ vlna, ne kde skončila)\nÚspěch → Jednotka 5: 3x7 @102 kg\nÚspěch → Jednotka 6: 3x6 @103 kg\nÚspěch → Jednotka 7: 3x8 @102 kg (další vlna)\n\nSmysl: každá celá vlna zvýší vlastní počáteční váhu vlny o jeden přírůstek, zatímco v rámci vlny váha na chvíli stoupá výš za cenu méně opakování, místo aby se pokaždé úplně resetovala zpět dolů.\n\nKaždá jednotlivá pracovní série musí dosáhnout alespoň aktuálního cíle opakování - pokud i jen jedna série tento cíl nesplní, celá jednotka se počítá jako neúspěšná: váha i cíl opakování zůstávají přesně stejné a další jednotka opakuje identický pokus.',
    'config.waveProgressionInitialRepsLabel': 'Počáteční opakování',
    'config.waveProgressionFinalRepsLabel': 'Konečná opakování',
    'config.waveProgressionDecrementLabel': 'Pokles opakování za jednotku',
    'config.restsTitle': 'Odpočinky',
    'config.restsOverrideHint': 'Tyto hodnoty platí jako výchozí pro každý cvik a lze je individuálně přepsat u cviků v tréninkových plánech a tréninkových jednotkách.',
    'config.firstRestAfterSetLabel': '1. odpočinek',
    'config.firstRestAfterSetTooltip': 'Čekací doba po sérii do prvního připomínkového gongu.',
    'config.secondRestAfterSetLabel': '2. odpočinek',
