    'config.restBetweenExercisesLabel': 'Odpočinek mezi cviky',
    'config.autoTrainingSessionTitle': 'Automatizovaná tréninková jednotka',
    'config.autoTrainingSessionHint': 'Určuje, co se stane, jakmile jsou dokončeny všechny série v sekci: zda se automaticky přepne na další sekci, která má ještě otevřené série - v případě potřeby i na další cvik.',
    'config.warmupSetsAutoAdvanceLabel': 'Rozcvičovací série',
    'config.workingSetsAutoAdvanceLabel': 'Pracovní série',
    'config.autoAdvanceImmediateOption': 'Přejít hned po poslední sérii',
    'config.autoAdvanceConfirmOption': 'Nejdřív se zeptat',
    'config.autoAdvanceOffOption': 'Žádná automatizace',
    'sessions.autoAdvanceToWorkingQuestion': 'Všechny rozcvičovací série jsou dokončeny. Přepnout na pracovní série?',
    'sessions.autoAdvanceToCooldownQuestion': 'Všechny pracovní série jsou dokončeny. Přepnout na zklidnění?',
    'sessions.autoAdvanceWarmupToCooldownQuestion': 'Všechny rozcvičovací série jsou dokončeny. Přepnout na zklidnění?',
    'sessions.autoAdvanceToNextExerciseQuestion': 'Všechny série zde jsou dokončeny. Přepnout na další cvik?',
    'config.linearProgressionTitle': 'Lineární progrese',
    'config.linearProgressionDescription': 'Lineární progrese: klasický styl StrongLifts/Starting Strength. Každá pracovní série musí dosáhnout vlastního pevného minimálního počtu opakování (obvykle stejného napříč sériemi, např. 3x5, ale nastavitelného pro každou sérii zvlášť), aby se příští jednotku zvýšila váha; nesplníš i jen jednu sérii a stejná váha se opakuje, abys to mohl zkusit znovu. Na rozdíl od ostatních schémat zde není žádné globální výchozí nastavení - minimální počet opakování se nastavuje přímo u každého cviku v jeho tréninkovém plánu. Toto je výchozí schéma progrese pro nově přidané cviky.',
