    'config.doubleProgressionTitle': 'Çift İlerleme',
    'config.incrementSchemeDescription':
      'Çift ilerleme: aynı prensip için iki farklı ilerleme modu. 8-10 tekrar aralığıyla örnek.\n\n"Her sete bir tekrar ekle" modu (daha basit):\nSeans 1: 3x8 (her sette 8 tekrar)\nBaşarı → Seans 2: 3x9\nBaşarı → Seans 3: 3x10 (aralığın üst sınırına ulaşıldı)\nBaşarı → ağırlık artar, yeni ağırlıkla tekrar 3x8’e dönülür\n\n"Toplamda bir ekstra tekrar ekle" modu (daha yumuşak, 4 set örneği):\nSeans 1: 4x8\nBaşarı → Seans 2: 1x9 + 3x8 (sadece bir set ekstra tekrarı alır, hepsi birden değil)\nBaşarı → Seans 3: 2x9 + 2x8\nBaşarı → Seans 4: 3x9 + 1x8\nBaşarı → Seans 5: 4x9 (artık her set 9’a yetişti)\nBaşarı → Seans 6: 1x10 + 3x9\nBaşarı → Seans 7: 2x10 + 2x9\nBaşarı → Seans 8: 3x10 + 1x9\nBaşarı → Seans 9: 4x10 (aralığın üst sınırına ulaşıldı)\nBaşarı → ağırlık artar, tekrar 4x8’e dönülür\n\nBu ikinci modun amacı: artış daha fazla seansa yayılır (4 setle, tam bir döngü sadece 3 yerine 9 seans sürer), çünkü her seansta her sete bir tane daha eklemek yerine sadece toplamda tek bir tekrar eklenir.\n\n"Bir set yalnızca bir kez sayılır..." şu anlama gelir: her bir set, o seans için kendi hedefine göre kontrol edilir. Bir set bile hedefini kaçırırsa (ör. 2x9+2x8’de, 9 tekrarlık setlerden biri sadece 8’e ulaşırsa), tüm seans başarısız sayılır - bir sonraki seans tam olarak aynı hedefleri tekrarlar (geri adım yok, ama ilerleme de yok).',
    'config.incrementSchemeRepRange': 'Hedef Tekrar',
    'config.incrementSchemeModeAllSets': 'Her seansta her sete bir tekrar ekle',
    'config.incrementSchemeModeOneTotalRep': 'Her seansta toplamda bir ekstra tekrar ekle',
    'config.repGoalTitle': 'Tekrar Hedefi Sistemi',
    'config.repGoalDescription':
      'Tekrar hedefi sistemi: set başına sabit bir hedef yerine, her çalışma seti yorgunluğa yakın bir noktaya kadar götürülür ve serbestçe kaydedilir. Tüm çalışma setlerindeki tekrarlar seans sonunda toplanır (ör. 8+8+6+6 = 28) ve toplam tekrar hedefiyle karşılaştırılır. Hedefi aşarsan ağırlık bir sonraki seansta artar; yetersiz kalırsan tekrar denemen için aynı ağırlık tekrarlanır.',
    'config.repGoalTotalRepGoalLabel': 'Tekrar hedefi',
    'config.waveProgressionTitle': 'Dalga İlerlemesi',
    'config.waveProgressionDescription':
      'Dalga ilerlemesi: her çalışma seti her zaman aynı tekrar hedefini ve ağırlığı paylaşır - çift ilerlemenin aksine, set başına bir değişiklik yoktur.\n\nBaşlangıç tekrarı 8, Bitiş tekrarı 6, Tekrar azaltma 1, başlangıç ağırlığı 100 kg ile örnek:\nSeans 1: 3x8 @100 kg\nBaşarı → Seans 2: 3x7 @101 kg\nBaşarı → Seans 3: 3x6 @102 kg (Bitiş tekrarına ulaşıldı)\nBaşarı → yeni dalga, Seans 4: 3x8 @101 kg (ÖNCEKİ dalganın bittiği yerde değil, başladığı yerin bir artış üstünde)\nBaşarı → Seans 5: 3x7 @102 kg\nBaşarı → Seans 6: 3x6 @103 kg\nBaşarı → Seans 7: 3x8 @102 kg (sonraki dalga)\n\nAmaç şu: her tam dalga, dalganın kendi başlangıç ağırlığını bir artış yükseltir; bir dalga içindeyken ağırlık, her seferinde tamamen en başa dönmek yerine, daha az tekrar pahasına bir süre daha yükseğe tırmanır.\n\nHer bir çalışma seti en azından güncel tekrar hedefine ulaşmalıdır - bir set bile bunu kaçırırsa tüm seans başarısız sayılır: ağırlık ve tekrar hedefi tamamen aynı kalır ve bir sonraki seans aynı denemeyi tekrarlar.',
    'config.waveProgressionInitialRepsLabel': 'Başlangıç tekrarı',
    'config.waveProgressionFinalRepsLabel': 'Bitiş tekrarı',
    'config.waveProgressionDecrementLabel': 'Seans başına tekrar azaltma',
