    'config.plateDuplicateError': 'يوجد بالفعل قرص بهذا الوزن والقطر.',
    'config.doubleProgressionTitle': 'التدرج المزدوج',
    'config.incrementSchemeDescription': 'التدرج المزدوج: نمطا تدرج مختلفان لنفس المبدأ. مثال بنطاق تكرار 8-10.\n\nنمط "إضافة تكرار إلى كل مجموعة" (الأبسط):\nالجلسة 1: 3x8 (كل مجموعة 8 تكرارات)\nنجاح ← الجلسة 2: 3x9\nنجاح ← الجلسة 3: 3x10 (بلوغ أعلى النطاق)\nنجاح ← يرتفع الوزن، والعودة إلى 3x8 بالوزن الجديد\n\nنمط "إضافة تكرار إجمالي واحد" (الأكثر تدرجاً، مثال بـ 4 مجموعات):\nالجلسة 1: 4x8\nنجاح ← الجلسة 2: 1x9 + 3x8 (مجموعة واحدة فقط تحصل على التكرار الإضافي، وليس الجميع دفعة واحدة)\nنجاح ← الجلسة 3: 2x9 + 2x8\nنجاح ← الجلسة 4: 3x9 + 1x8\nنجاح ← الجلسة 5: 4x9 (لحقت كل مجموعة الآن بـ 9)\nنجاح ← الجلسة 6: 1x10 + 3x9\nنجاح ← الجلسة 7: 2x10 + 2x9\nنجاح ← الجلسة 8: 3x10 + 1x9\nنجاح ← الجلسة 9: 4x10 (بلوغ أعلى النطاق)\nنجاح ← يرتفع الوزن، والعودة إلى 4x8\n\nالغاية من هذا النمط الثاني: تنتشر الزيادة عبر جلسات أكثر (مع 4 مجموعات، تستغرق الدورة الكاملة 9 جلسات بدلاً من 3 فقط)، لأنه يُضاف تكرار إجمالي واحد فقط في كل جلسة بدلاً من تكرار إضافي على كل مجموعة دفعة واحدة.\n\n"المجموعة تُحتسب مرة واحدة فقط..." يعني: يُقارَن كل مجموعة على حدة بهدفها الخاص لتلك الجلسة. فإذا فوّتت مجموعة واحدة هدفها (مثلاً في 2x9+2x8، إحدى مجموعات الـ9 تكرارات حققت 8 فقط)، تُحتسب الجلسة بأكملها غير ناجحة - وتكرر الجلسة التالية نفس الأهداف تماماً (بلا تراجع، لكن بلا تقدم أيضاً).',
    'config.incrementSchemeRepRange': 'التكرارات المستهدفة',
    'config.incrementSchemeModeAllSets': 'إضافة تكرار إلى كل مجموعة في كل جلسة',
    'config.incrementSchemeModeOneTotalRep': 'إضافة تكرار إجمالي واحد في كل جلسة',
    'config.repGoalTitle': 'نظام هدف التكرارات',
    'config.repGoalDescription': 'نظام هدف التكرارات: بدلاً من هدف ثابت لكل مجموعة، تُدفع كل مجموعة عمل قريباً من الفشل وتُسجَّل بحرية. تُجمع تكرارات جميع مجموعات العمل في نهاية الجلسة (مثلاً 8+8+6+6 = 28) وتُقارن بهدف التكرارات الإجمالي. إذا تجاوزت الهدف يرتفع الوزن في الجلسة التالية؛ وإذا قصّرت يُكرر نفس الوزن لتحاول مجدداً.',
    'config.repGoalTotalRepGoalLabel': 'هدف التكرارات',
    'config.waveProgressionTitle': 'التدرج الموجي',
    'config.waveProgressionDescription': 'التدرج الموجي: تشترك كل مجموعات العمل دائماً في نفس هدف التكرارات والوزن - على عكس التدرج المزدوج، لا يوجد تفاوت لكل مجموعة.\n\nمثال بتكرارات ابتدائية 8، وتكرارات نهائية 6، وخفض تكرار 1، ووزن بداية 100 kg:\nالجلسة 1: 3x8 @100 kg\nنجاح ← الجلسة 2: 3x7 @101 kg\nنجاح ← الجلسة 3: 3x6 @102 kg (بلوغ التكرارات النهائية)\nنجاح ← موجة جديدة، الجلسة 4: 3x8 @101 kg (بزيادة واحدة فوق نقطة بداية الموجة السابقة، وليس نهايتها)\nنجاح ← الجلسة 5: 3x7 @102 kg\nنجاح ← الجلسة 6: 3x6 @103 kg\nنجاح ← الجلسة 7: 3x8 @102 kg (الموجة التالية)\n\nالغاية: ترفع كل موجة كاملة وزن بداية الموجة نفسها بزيادة واحدة، بينما يرتفع الوزن داخل الموجة الواحدة لفترة على حساب تكرارات أقل، بدلاً من العودة كل مرة إلى الأسفل تماماً.\n\nيجب أن تبلغ كل مجموعة عمل على حدة هدف التكرارات الحالي على الأقل - فإذا فوّتته مجموعة واحدة، تُحتسب الجلسة بأكملها غير ناجحة: يبقى الوزن وهدف التكرارات كما هما تماماً، وتُكرر الجلسة التالية المحاولة ذاتها.',
