    'config.linearProgressionDescription': 'التدرج الخطي: النمط الكلاسيكي على طراز StrongLifts/Starting Strength. يجب أن تبلغ كل مجموعة عمل حدها الأدنى الثابت من التكرارات (عادة نفس العدد عبر المجموعات، مثل 3x5، لكنه قابل للتعديل لكل مجموعة) ليرتفع الوزن في الجلسة التالية؛ وإذا فوّتت مجموعة واحدة فقط يُكرر نفس الوزن لتحاول مجدداً. وعلى عكس الأنظمة الأخرى هنا، لا يوجد إعداد افتراضي عام - يُحدَّد الحد الأدنى للتكرارات مباشرة على كل تمرين في خطة تدريبه. هذا هو نظام التدرج الافتراضي للتمارين المضافة حديثاً.',

