    'config.incrementSchemeDescription':
      '双重递增：针对同一原则的两种不同递增模式。以8-10次的次数范围为例。\n\n“每组增加一次”模式（较简单）：\n课程1：3x8（每组8次）\n成功 → 课程2：3x9\n成功 → 课程3：3x10（达到区间上限）\n成功 → 重量增加，以新重量回到3x8\n\n“总共增加一次”模式（较温和，以4组为例）：\n课程1：4x8\n成功 → 课程2：1x9 + 3x8（只有一组获得额外的一次，而非一次性全部增加）\n成功 → 课程3：2x9 + 2x8\n成功 → 课程4：3x9 + 1x8\n成功 → 课程5：4x9（此时每组都已追上到9次）\n成功 → 课程6：1x10 + 3x9\n成功 → 课程7：2x10 + 2x9\n成功 → 课程8：3x10 + 1x9\n成功 → 课程9：4x10（达到区间上限）\n成功 → 重量增加，回到4x8\n\n这第二种模式的意义在于：增加过程分摊到更多课程中（以4组为例，完整一个周期需要9次课程，而不是仅3次），因为每次课程只增加总共一次，而不是一次性给每组都增加一次。\n\n“每组只计一次……”的意思是：每一组都会依据该课程自身的目标单独核查。只要有一组未达到目标（例如在2x9+2x8中，其中一组本该9次却只完成了8次），整次课程就算不成功——下一次课程会原样重复相同的目标（不会退步，但也没有进展）。',
    'config.incrementSchemeRepRange': '目标次数',
    'config.incrementSchemeModeAllSets': '每次课程为每组增加一次',
    'config.incrementSchemeModeOneTotalRep': '每次课程总共增加一次',
    'config.repGoalTitle': '次数目标系统',
    'config.repGoalDescription':
      '次数目标系统：不为每组设定固定目标，而是让每个工作组都尽量接近力竭并自由记录次数。课程结束时，将所有工作组的次数相加（例如8+8+6+6 = 28），并与总次数目标进行比较。超过目标，下次课程重量就增加；未达到目标，则重复相同重量以便再次尝试。',
    'config.repGoalTotalRepGoalLabel': '次数目标',
    'config.waveProgressionTitle': '波动递增',
    'config.waveProgressionDescription':
      '波动递增：每个工作组始终共享相同的目标次数和重量——与双重递增不同，这里没有按组变化。\n\n以起始次数8、最终次数6、次数递减1、起始重量100 kg为例：\n课程1：3x8 @100 kg\n成功 → 课程2：3x7 @101 kg\n成功 → 课程3：3x6 @102 kg（达到最终次数）\n成功 → 新一轮波动，课程4：3x8 @101 kg（比上一轮波动的起始重量高一个增量，而非比其结束重量高）\n成功 → 课程5：3x7 @102 kg\n成功 → 课程6：3x6 @103 kg\n成功 → 课程7：3x8 @102 kg（下一轮波动）\n\n要点：每完成一轮完整的波动，该波动自身的起始重量就提高一个增量，而在一轮波动内部，重量会在一段时间内持续攀升，代价是次数减少，而不是每次都彻底回落。\n\n每个工作组都必须至少达到当前的目标次数——只要有一组未达到，整次课程就算不成功：重量和目标次数保持完全不变，下次课程重复相同的尝试。',
    'config.waveProgressionInitialRepsLabel': '起始次数',
    'config.waveProgressionFinalRepsLabel': '最终次数',
    'config.waveProgressionDecrementLabel': '每次课程的次数递减',
    'config.restsTitle': '休息',
    'config.restsOverrideHint': '这些数值作为每个动作的默认设置，可在训练计划和训练课程的各个动作中单独覆盖。',
    'config.firstRestAfterSetLabel': '第1次休息',
    'config.firstRestAfterSetTooltip': '一组结束后到第一次提醒锣声的等待时间。',
