    'config.secondRestAfterSetTooltip': '一组结束后到第二次锣声的等待时间——从与第一次相同的时刻计算，而非叠加。数值 ≤ 第1次休息：只响一次锣。',
    'config.restBetweenExercisesLabel': '动作之间的休息',
    'config.autoTrainingSessionTitle': '自动化训练课程',
    'config.autoTrainingSessionHint':
      '控制某个部分的所有组完成后会发生什么：是否自动切换到仍有未完成组的下一部分——如有必要，甚至切换到下一个动作。',
    'config.warmupSetsAutoAdvanceLabel': '热身组',
