    'sessions.autoAdvanceWarmupToCooldownQuestion': '所有热身组均已完成。是否切换到放松？',
    'sessions.autoAdvanceToNextExerciseQuestion': '此处所有组均已完成。是否切换到下一个动作？',
    'config.linearProgressionTitle': '线性递增',
    'config.linearProgressionDescription':
      '线性递增：经典的StrongLifts／Starting Strength风格。每个工作组都必须达到各自固定的最低次数（通常各组相同，例如3x5，但可按组调整），下次课程重量才会增加；只要有一组未达标，就重复相同重量以便再次尝试。与这里的其他方案不同，没有可配置的全局默认值——最低次数是直接在训练计划的每个动作上设置的。这是新添加动作的默认递增方案。',

