    'config.plateDuplicateError': 'この重量と直径のプレートはすでに存在します。',
    'config.doubleProgressionTitle': 'ダブルプログレッション',
    'config.incrementSchemeDescription': 'ダブルプログレッション:同じ原則に基づく2つの異なる進行モードです。8-10レップレンジの例。\n\n「毎セッション、すべてのセットにレップを1つ追加する」モード(よりシンプル):\nセッション1:3x8(すべてのセットで8レップ)\n成功 → セッション2:3x9\n成功 → セッション3:3x10(レンジの上限に到達)\n成功 → 重量が上がり、新しい重量で3x8に戻る\n\n「毎セッション、合計で1レップだけ追加する」モード(より緩やか、4セットの例):\nセッション1:4x8\n成功 → セッション2:1x9 + 3x8(一度に全セットではなく、1セットだけが追加レップを行う)\n成功 → セッション3:2x9 + 2x8\n成功 → セッション4:3x9 + 1x8\n成功 → セッション5:4x9(すべてのセットが9に追いついた)\n成功 → セッション6:1x10 + 3x9\n成功 → セッション7:2x10 + 2x9\n成功 → セッション8:3x10 + 1x9\n成功 → セッション9:4x10(レンジの上限に到達)\n成功 → 重量が上がり、4x8に戻る\n\nこの2つ目のモードのポイント:一度にすべてのセットに1レップずつ追加するのではなく、毎セッション合計で1レップだけ追加するため、増加がより多くのセッションに分散されます(4セットの場合、1サイクルはわずか3セッションではなく9セッションかかります)。\n\n「セットは一度だけカウントされる…」とは:個々のセットはすべて、そのセッションにおける自身の目標と照合されます。1つでもセットが目標を逃した場合(例:2x9+2x8で、9レップのセットの1つが8レップしかできなかった場合)、そのセッション全体が失敗としてカウントされます — 次のセッションではまったく同じ目標が繰り返されます(後退はしませんが、進行もありません)。',
    'config.incrementSchemeRepRange': '目標レップ数',
    'config.incrementSchemeModeAllSets': '毎セッション、すべてのセットにレップを1つ追加する',
    'config.incrementSchemeModeOneTotalRep': '毎セッション、合計で1レップだけ追加する',
    'config.repGoalTitle': 'レップゴールシステム',
    'config.repGoalDescription': 'レップゴールシステム:セットごとに固定の目標を設定する代わりに、各ワーキングセットを限界に近いところまで追い込み、自由に記録します。セッション終了時にすべてのワーキングセットのレップ数を合計し(例:8+8+6+6 = 28)、合計レップゴールと比較します。ゴールを上回れば次のセッションで重量が上がり、届かなければ同じ重量を繰り返して再挑戦します。',
    'config.repGoalTotalRepGoalLabel': 'レップゴール',
    'config.waveProgressionTitle': 'ウェーブプログレッション',
    'config.waveProgressionDescription': 'ウェーブプログレッション:ワーキングセットは常にすべて同じ目標レップ数と重量を共有します — ダブルプログレッションとは異なり、セットごとのばらつきはありません。\n\n開始レップ8、終了レップ6、レップ減少数1、開始重量100 kgの例:\nセッション1:3x8 @100 kg\n成功 → セッション2:3x7 @101 kg\n成功 → セッション3:3x6 @102 kg(終了レップに到達)\n成功 → 新しいウェーブ、セッション4:3x8 @101 kg(前のウェーブの終了時点ではなく、開始時点より1増分高い)\n成功 → セッション5:3x7 @102 kg\n成功 → セッション6:3x6 @103 kg\n成功 → セッション7:3x8 @102 kg(次のウェーブ)\n\nポイント:毎回すべてを最初までリセットするのではなく、各ウェーブがそのウェーブ自身の開始重量を1増分ずつ引き上げ、ウェーブの中では一時的にレップ数を減らす代わりに重量がより高く上がっていきます。\n\n個々のワーキングセットはすべて、現在の目標レップ数に最低でも到達する必要があります — 1つでもセットが逃した場合、そのセッション全体が失敗としてカウントされます:重量と目標レップ数はまったく同じままとなり、次のセッションでも同一の挑戦が繰り返されます。',
    'config.waveProgressionInitialRepsLabel': '開始レップ数',
