    'config.linearProgressionDescription': 'リニアプログレッション:StrongLiftsやStarting Strengthのクラシックなスタイルです。次のセッションで重量が増加するには、すべてのワーキングセットがそれぞれ固定の最低レップ数(通常はすべてのセットで同じ、例:3x5ですが、セットごとに調整可能)に達する必要があります。1つでもセットを逃せば同じ重量を繰り返して再挑戦します。他のスキームとは異なり、設定するグローバルなデフォルトはありません — 最低レップ数はトレーニングプラン内の各エクササイズで直接設定します。これは新しく追加されたエクササイズのデフォルトの進行スキームです。',
