    'exercises.customOneRepMaxTooltip': 'Χειροκίνητα καταχωρημένο 1RM, που χρησιμοποιείται για την πρόοδο βασισμένη σε ποσοστό αντί για το εκτιμώμενο μέγιστο παραπάνω όταν είναι επιλεγμένο το "Χρήση Προσαρμοσμένου 1RM".',
