    'config.doubleProgressionTitle': 'Διπλή Πρόοδος',
    'config.incrementSchemeDescription': 'Διπλή πρόοδος: δύο διαφορετικές λειτουργίες προόδου για την ίδια αρχή. Παράδειγμα με εύρος επαναλήψεων 8-10.\n\nΛειτουργία "Προσθήκη μίας επανάληψης σε κάθε σετ" (πιο απλή):\nΣυνεδρία 1: 3x8 (κάθε σετ 8 επαναλήψεις)\nΕπιτυχία → Συνεδρία 2: 3x9\nΕπιτυχία → Συνεδρία 3: 3x10 (επιτεύχθηκε η κορυφή του εύρους)\nΕπιτυχία → το βάρος ανεβαίνει, επιστροφή σε 3x8 με το νέο βάρος\n\nΛειτουργία "Προσθήκη μίας συνολικά επιπλέον επανάληψης" (πιο ήπια, παράδειγμα με 4 σετ):\nΣυνεδρία 1: 4x8\nΕπιτυχία → Συνεδρία 2: 1x9 + 3x8 (μόνο ένα σετ παίρνει την επιπλέον επανάληψη, όχι όλα ταυτόχρονα)\nΕπιτυχία → Συνεδρία 3: 2x9 + 2x8\nΕπιτυχία → Συνεδρία 4: 3x9 + 1x8\nΕπιτυχία → Συνεδρία 5: 4x9 (κάθε σετ έχει πλέον φτάσει στις 9)\nΕπιτυχία → Συνεδρία 6: 1x10 + 3x9\nΕπιτυχία → Συνεδρία 7: 2x10 + 2x9\nΕπιτυχία → Συνεδρία 8: 3x10 + 1x9\nΕπιτυχία → Συνεδρία 9: 4x10 (επιτεύχθηκε η κορυφή του εύρους)\nΕπιτυχία → το βάρος ανεβαίνει, επιστροφή σε 4x8\n\nΤο νόημα αυτής της δεύτερης λειτουργίας: η αύξηση απλώνεται σε περισσότερες συνεδρίες (με 4 σετ, ένας πλήρης κύκλος χρειάζεται 9 συνεδρίες αντί για μόλις 3), καθώς προστίθεται μόνο μία συνολική επανάληψη ανά συνεδρία αντί για μία επιπλέον σε κάθε σετ ταυτόχρονα.\n\nΤο "Ένα σετ μετράει μόνο μία φορά..." σημαίνει: κάθε μεμονωμένο σετ ελέγχεται ως προς τον δικό του στόχο για αυτή τη συνεδρία. Αν έστω και ένα σετ χάσει τον στόχο του (π.χ. στο 2x9+2x8, ένα από τα σετ των 9 επαναλήψεων φτάνει μόνο τις 8), όλη η συνεδρία μετράει ως ανεπιτυχής - η επόμενη συνεδρία επαναλαμβάνει ακριβώς τους ίδιους στόχους (χωρίς οπισθοχώρηση, αλλά και χωρίς πρόοδο).',
    'config.incrementSchemeRepRange': 'Στόχος Επαναλήψεων',
