    'config.repGoalDescription': 'Σύστημα στόχου επαναλήψεων: αντί για σταθερό στόχο ανά σετ, κάθε σετ εργασίας πιέζεται κοντά στην εξάντληση και καταγράφεται ελεύθερα. Οι επαναλήψεις όλων των σετ εργασίας αθροίζονται στο τέλος της συνεδρίας (π.χ. 8+8+6+6 = 28) και συγκρίνονται με τον συνολικό στόχο επαναλήψεων. Αν ξεπεράσεις τον στόχο, το βάρος ανεβαίνει την επόμενη συνεδρία· αν μείνεις χαμηλότερα, επαναλαμβάνεται το ίδιο βάρος ώστε να προσπαθήσεις ξανά.',
    'config.repGoalTotalRepGoalLabel': 'Στόχος επαναλήψεων',
    'config.waveProgressionTitle': 'Κυματοειδής Πρόοδος',
    'config.waveProgressionDescription': 'Κυματοειδής πρόοδος: κάθε σετ εργασίας μοιράζεται πάντα τον ίδιο στόχο επαναλήψεων και το ίδιο βάρος - σε αντίθεση με τη διπλή πρόοδο, δεν υπάρχει διαφοροποίηση ανά σετ.\n\nΠαράδειγμα με Αρχικές επαναλήψεις 8, Τελικές επαναλήψεις 6, Μείωση επαναλήψεων 1, αρχικό βάρος 100 kg:\nΣυνεδρία 1: 3x8 @100 kg\nΕπιτυχία → Συνεδρία 2: 3x7 @101 kg\nΕπιτυχία → Συνεδρία 3: 3x6 @102 kg (επιτεύχθηκαν οι τελικές επαναλήψεις)\nΕπιτυχία → νέο κύμα, Συνεδρία 4: 3x8 @101 kg (ένα βήμα πάνω από εκεί που ξεκίνησε το ΠΡΟΗΓΟΥΜΕΝΟ κύμα, όχι εκεί που τελείωσε)\nΕπιτυχία → Συνεδρία 5: 3x7 @102 kg\nΕπιτυχία → Συνεδρία 6: 3x6 @103 kg\nΕπιτυχία → Συνεδρία 7: 3x8 @102 kg (επόμενο κύμα)\n\nΤο νόημα: κάθε πλήρες κύμα αυξάνει το δικό του αρχικό βάρος κατά ένα βήμα, ενώ μέσα σε ένα κύμα το βάρος ανεβαίνει για λίγο με το κόστος λιγότερων επαναλήψεων, αντί να επιστρέφει κάθε φορά εντελώς στην αρχή.\n\nΚάθε μεμονωμένο σετ εργασίας πρέπει να φτάσει τουλάχιστον τον τρέχοντα στόχο επαναλήψεων - αν έστω και ένα σετ τον χάσει, όλη η συνεδρία μετράει ως ανεπιτυχής: το βάρος και ο στόχος επαναλήψεων παραμένουν ακριβώς ίδια, και η επόμενη συνεδρία επαναλαμβάνει την ίδια ακριβώς προσπάθεια.',
